INSERT INTO Translation VALUES('2a4c6e8f-5b7d-4f9a-8c1e-3d4e5f6a7b8c','∀x ∈ ℝ, x ≠ 0 ∧ x² > 0','∀x ∈ ℝ, x ≠ 0 ∧ x² > 0');
