INSERT INTO Translation VALUES('9a1c2d3e-5f6a-4b7c-8d9e-8e9f1a2b3c4d','∀x((x² ≤ 0) → (x = 0))','∀x((x² ≤ 0) → (x = 0))');
INSERT INTO Translation VALUES('1b2d3f4a-6c7e-4d8f-9a1b-9f1a2b3c4d5e','∀x((x > 0) ∨ (x < 0) ∨ (x² > 0))','∀x((x > 0) ∨ (x < 0) ∨ (x² > 0))');
