INSERT INTO Translation VALUES('67cb3992-ad01-4a69-9738-1eacf9bd0985','How many integers from 1 to 100 are divisible by 3 or 7?','כמה מספרים שלמים בין 1 ל-100 מתחלקים ב-3 או ב-7?');
