INSERT INTO Translation VALUES('4b6c8d1e-3f5a-4d7b-af8c-5e9f1a2b3c4d','The Fundamental Formula of the Definite Integral','הנוסחה היסודית של האינטגרל המסוים');
INSERT INTO Translation VALUES('f8a1e3d5-6b9c-4f2a-8e1f-3a5c7d9e2b4f','Upper Sums','סכומים עליונים');
INSERT INTO Translation VALUES('2c4e6a8f-1d3f-4a7c-9e2a-5f8a1c3e6d9f','Lower Sums','סכומים תחתונים');
INSERT INTO Translation VALUES('482223b5-7343-4270-bff1-a9c3d934fa28','What is an upper sum in the context of Riemann integration?','מהו סכום עליון בהקשר של אינטגרל רימן?');
INSERT INTO Translation VALUES('2206522e-c241-4745-92aa-cdc9530b1e92','The sum using the maximum value of the function in each subinterval','הסכום באמצעות הערך המקסימלי של הפונקציה בכל תת-רווח');
INSERT INTO Translation VALUES('2351c70a-3dea-4239-8bd5-2f61e2959bee','The sum using the minimum value of the function in each subinterval','הסכום באמצעות הערך המינימלי של הפונקציה בכל תת-רווח');
INSERT INTO Translation VALUES('c5905fc5-f356-4f54-be05-cfd3bb39d08d','The sum using the average value of the function in each subinterval','הסכום באמצעות הערך הממוצע של הפונקציה בכל תת-רווח');
INSERT INTO Translation VALUES('8a0e3cad-d137-4af7-9431-21a742678f01','The sum using the midpoint value of the function in each subinterval','הסכום באמצעות ערך נקודת האמצע של הפונקציה בכל תת-רווח');
INSERT INTO Translation VALUES('44a0d45b-2963-4836-94d7-90006e95caca','How do upper sums relate to the definite integral?','איך סכומים עליונים קשורים לאינטגרל המסוים?');
INSERT INTO Translation VALUES('7b75b3a0-465f-4fdf-94e5-eb292e32bf9f','Upper sums provide an upper bound for the definite integral','סכומים עליונים מספקים חסם עליון לאינטגרל המסוים');
INSERT INTO Translation VALUES('de34861c-e147-46b8-a745-d7ed612c73ae','Upper sums provide a lower bound for the definite integral','סכומים עליונים מספקים חסם תחתון לאינטגרל המסוים');
INSERT INTO Translation VALUES('ae05ff78-bb6e-4b63-ac36-bd2efb9edf11','Upper sums equal the definite integral exactly','סכומים עליונים שווים לאינטגרל המסוים בדיוק');
INSERT INTO Translation VALUES('6a76c035-9130-414a-8f3b-625e3c65c3c2','Upper sums are unrelated to the definite integral','סכומים עליונים לא קשורים לאינטגרל המסוים');
INSERT INTO Translation VALUES('eb64b28c-dd31-4e71-89c7-f19821d872be','What is a lower sum in the context of Riemann integration?','מהו סכום תחתון בהקשר של אינטגרל רימן?');
INSERT INTO Translation VALUES('8c7227a4-ae19-4eb3-94b9-9e1f92a94f63','The sum using the minimum value of the function in each subinterval for lower sums','הסכום באמצעות הערך המינימלי של הפונקציה בכל תת-רווח עבור סכומים תחתונים');
INSERT INTO Translation VALUES('dea72d18-13ad-41c6-b4bd-dafac603f133','The sum using the maximum value of the function in each subinterval for lower sums','הסכום באמצעות הערך המקסימלי של הפונקציה בכל תת-רווח עבור סכומים תחתונים');
INSERT INTO Translation VALUES('d55a2d19-8c0f-4430-a3e1-f5873389a00e','The sum using the average value of the function in each subinterval for lower sums','הסכום באמצעות הערך הממוצע של הפונקציה בכל תת-רווח עבור סכומים תחתונים');
INSERT INTO Translation VALUES('3d5966d9-6655-4639-b902-2de703c3da38','The sum using the midpoint value of the function in each subinterval for lower sums','הסכום באמצעות ערך נקודת האמצע של הפונקציה בכל תת-רווח עבור סכומים תחתונים');
INSERT INTO Translation VALUES('ab1f213f-f85b-4a48-a59c-06fd93019eaf','How do lower sums relate to the definite integral?','איך סכומים תחתונים קשורים לאינטגרל המסוים?');
INSERT INTO Translation VALUES('9531b9c1-1f3d-49e6-bfb4-c0d8384caf9e','Lower sums provide a lower bound for the definite integral','סכומים תחתונים מספקים חסם תחתון לאינטגרל המסוים');
INSERT INTO Translation VALUES('3d6f492d-b7fa-4f17-b431-1fed4b1a7b2b','Lower sums provide an upper bound for the definite integral','סכומים תחתונים מספקים חסם עליון לאינטגרל המסוים');
INSERT INTO Translation VALUES('346813c9-f3cf-4827-9bb9-1e2d4da7b70f','Lower sums equal the definite integral exactly','סכומים תחתונים שווים לאינטגרל המסוים בדיוק');
INSERT INTO Translation VALUES('3c74abda-7c59-41de-8c17-cfcb2305fb56','Lower sums are unrelated to the definite integral','סכומים תחתונים לא קשורים לאינטגרל המסוים');
INSERT INTO Translation VALUES('a8acbde6-b69c-4dfb-a02b-b86fab5ce020','What happens when the number of subintervals approaches infinity in upper and lower sums?','מה קורה כאשר מספר תת-הרווחים שואף לאינסוף בסכומים עליונים ותחתונים?');
INSERT INTO Translation VALUES('67b2e3fe-bfbb-40bb-99a7-270fac6841bf','Both upper and lower sums converge to the definite integral','גם סכומים עליונים וגם תחתונים מתכנסים לאינטגרל המסוים');
INSERT INTO Translation VALUES('49bfcb08-75db-4d6f-a9f2-5ec0839466a6','Only upper sums converge to the definite integral','רק סכומים עליונים מתכנסים לאינטגרל המסוים');
INSERT INTO Translation VALUES('6675796c-f296-4c91-b9e4-f1e316e1e40d','Only lower sums converge to the definite integral','רק סכומים תחתונים מתכנסים לאינטגרל המסוים');
INSERT INTO Translation VALUES('c90dfde3-0732-42af-a85f-7843ded1b8a2','Neither upper nor lower sums converge','לא סכומים עליונים ולא תחתונים מתכנסים');
INSERT INTO Translation VALUES('f1a2b3c4-1111-4567-890a-bcdef0123456','What is the Fundamental Formula of the Definite Integral?','מהי הנוסחה היסודית של האינטגרל המסוים?');
INSERT INTO Translation VALUES('f1a2b3c4-1111-4567-890a-bcdef0123458','∫[a,b] f(x)dx = F(b) - F(a), where F''(x) = f(x)','∫[a,b] f(x)dx = F(b) - F(a), כאשר F''(x) = f(x)');
INSERT INTO Translation VALUES('f1a2b3c4-1111-4567-890a-bcdef0123459','∫[a,b] f(x)dx = F(a) - F(b), where F''(x) = f(x)','∫[a,b] f(x)dx = F(a) - F(b), כאשר F''(x) = f(x)');
INSERT INTO Translation VALUES('f1a2b3c4-1111-4567-890a-bcdef012345a','∫[a,b] f(x)dx = F(b) + F(a), where F''(x) = f(x)','∫[a,b] f(x)dx = F(b) + F(a), כאשר F''(x) = f(x)');
INSERT INTO Translation VALUES('f1a2b3c4-1111-4567-890a-bcdef012345b','∫[a,b] f(x)dx = F''(b) - F''(a), where F(x) is any function','∫[a,b] f(x)dx = F''(b) - F''(a), כאשר F(x) פונקציה כלשהי');
INSERT INTO Translation VALUES('f2a2b3c4-2222-4567-890a-bcdef0123456','Calculate ∫[0,2] x dx using the Fundamental Formula','חשב ∫[0,2] x dx באמצעות הנוסחה היסודית');
INSERT INTO Translation VALUES('f3a2b3c4-3333-4567-890a-bcdef0123456','Calculate ∫[1,3] x² dx using the Fundamental Formula','חשב ∫[1,3] x² dx באמצעות הנוסחה היסודית');
INSERT INTO Translation VALUES('f4a2b3c4-4444-4567-890a-bcdef0123456','If F(x) = x³/3, what is ∫[0,2] x² dx?','אם F(x) = x³/3, מה הוא ∫[0,2] x² dx?');
INSERT INTO Translation VALUES('f5a2b3c4-5555-4567-890a-bcdef0123456','Calculate ∫[-1,1] 2x dx','חשב ∫[-1,1] 2x dx');
INSERT INTO Translation VALUES('f6a2b3c4-6666-4567-890a-bcdef0123456','What is the antiderivative of sin(x)?','מהו הפונקציה הקדומה של sin(x)?');
INSERT INTO Translation VALUES('f6a2b3c4-6666-4567-890a-bcdef0123458','-cos(x) + C','-cos(x) + C');
INSERT INTO Translation VALUES('f6a2b3c4-6666-4567-890a-bcdef0123459','cos(x) + C','cos(x) + C');
INSERT INTO Translation VALUES('f6a2b3c4-6666-4567-890a-bcdef012345a','-sin(x) + C','-sin(x) + C');
INSERT INTO Translation VALUES('f6a2b3c4-6666-4567-890a-bcdef012345b','tan(x) + C','tan(x) + C');
INSERT INTO Translation VALUES('f7a2b3c4-7777-4567-890a-bcdef0123456','Calculate ∫[0,π] sin(x) dx','חשב ∫[0,π] sin(x) dx');
INSERT INTO Translation VALUES('f8a2b3c4-8888-4567-890a-bcdef0123456','If f(x) = 3x² + 2x, calculate ∫[0,1] f(x) dx','אם f(x) = 3x² + 2x, חשב ∫[0,1] f(x) dx');
INSERT INTO Translation VALUES('f9a2b3c4-9999-4567-890a-bcdef0123456','What is ∫[1,e] (1/x) dx?','מה הוא ∫[1,e] (1/x) dx?');
INSERT INTO Translation VALUES('faa2b3c4-aaaa-4567-890a-bcdef0123456','The Fundamental Formula states that if F is an antiderivative of f, then which statement is true?','הנוסחה היסודית קובעת שאם F היא פונקציה קדומה של f, אז איזה מהטענות נכונה?');
INSERT INTO Translation VALUES('faa2b3c4-aaaa-4567-890a-bcdef0123458','The definite integral equals the difference of antiderivative values at the bounds','האינטגרל המסוים שווה להפרש ערכי הפונקציה הקדומה בקצוות');
INSERT INTO Translation VALUES('faa2b3c4-aaaa-4567-890a-bcdef0123459','The definite integral equals the sum of antiderivative values at the bounds','האינטגרל המסוים שווה לסכום ערכי הפונקציה הקדומה בקצוות');
INSERT INTO Translation VALUES('faa2b3c4-aaaa-4567-890a-bcdef012345a','The definite integral equals the product of antiderivative values at the bounds','האינטגרל המסוים שווה למכפלה של ערכי הפונקציה הקדומה בקצוות');
INSERT INTO Translation VALUES('faa2b3c4-aaaa-4567-890a-bcdef012345b','The definite integral equals the derivative of F at the bounds','האינטגרל המסוים שווה לנגזרת של F בקצוות');
INSERT INTO Translation VALUES('fba2b3c4-bbbb-4567-890a-bcdef0123456','Calculate ∫[0,4] √x dx','חשב ∫[0,4] √x dx');
INSERT INTO Translation VALUES('fca2b3c4-cccc-4567-890a-bcdef0123456','If ∫[a,b] f(x) dx = 0, what can we conclude about the function f on [a,b]?','אם ∫[a,b] f(x) dx = 0, מה ניתן להסיק על הפונקציה f ב-[a,b]?');
INSERT INTO Translation VALUES('fca2b3c4-cccc-4567-890a-bcdef0123458','The net area between f and the x-axis is zero','השטח נטו בין f לציר x הוא אפס');
INSERT INTO Translation VALUES('fca2b3c4-cccc-4567-890a-bcdef0123459','f(x) = 0 for all x in [a,b]','f(x) = 0 לכל x ב-[a,b]');
INSERT INTO Translation VALUES('fca2b3c4-cccc-4567-890a-bcdef012345a','f is constant on [a,b]','f קבועה ב-[a,b]');
INSERT INTO Translation VALUES('fca2b3c4-cccc-4567-890a-bcdef012345b','f is not integrable on [a,b]','f לא אינטגרבילית ב-[a,b]');
INSERT INTO Translation VALUES('fda2b3c4-dddd-4567-890a-bcdef0123456','Calculate ∫[0,π/2] cos(x) dx','חשב ∫[0,π/2] cos(x) dx');
INSERT INTO Translation VALUES('fea2b3c4-eeee-4567-890a-bcdef0123456','What is the antiderivative of e^x?','מהו הפונקציה הקדומה של e^x?');
INSERT INTO Translation VALUES('fea2b3c4-eeee-4567-890a-bcdef0123458','e^x + C','e^x + C');
INSERT INTO Translation VALUES('fea2b3c4-eeee-4567-890a-bcdef0123459','xe^x + C','xe^x + C');
INSERT INTO Translation VALUES('fea2b3c4-eeee-4567-890a-bcdef012345a','e^x/x + C','e^x/x + C');
INSERT INTO Translation VALUES('fea2b3c4-eeee-4567-890a-bcdef012345b','ln(e^x) + C','ln(e^x) + C');
INSERT INTO Translation VALUES('ffa2b3c4-ffff-4567-890a-bcdef0123456','Calculate ∫[1,2] (x³ - x) dx','חשב ∫[1,2] (x³ - x) dx');
