INSERT INTO Translation VALUES('6d8f2416-61eb-4d7c-9499-af265f0e2bbf','What is the determinant of the matrix [[2,5,3],[1,-2,0],[3,4,1]]?','מהו הדטרמיננטה של המטריצה [[2,5,3],[1,-2,0],[3,4,1]]?');
INSERT INTO Translation VALUES('428ea415-923a-4fb6-be7d-510a569bcb3b','What is the determinant of the matrix [[1,2,1],[0,1,0],[2,3,4]]?','מהו הדטרמיננטה של המטריצה [[1,2,1],[0,1,0],[2,3,4]]?');
INSERT INTO Translation VALUES('b70fe21c-11f4-4122-98bf-8594a2412f68','What is the determinant of the matrix [[4,1,2],[0,3,1],[2,0,5]]?','מהו הדטרמיננטה של המטריצה [[4,1,2],[0,3,1],[2,0,5]]?');
