INSERT INTO Translation VALUES('edefe330-a9bc-4eda-94e9-9fd172313023','What is the determinant of the matrix [[3,2,1],[1,0,4],[2,5,6]]?','מהו הדטרמיננטה של המטריצה [[3,2,1],[1,0,4],[2,5,6]]?');
INSERT INTO Translation VALUES('acad4524-e5c5-418e-9049-f4cc51e3fbd9','What is the determinant of the matrix [[0,2,1],[3,1,4],[5,-2,0]]?','מהו הדטרמיננטה של המטריצה [[0,2,1],[3,1,4],[5,-2,0]]?');
INSERT INTO Translation VALUES('2d1da962-4d25-4cde-8a06-9d338b07fe3c','What is the determinant of the matrix [[1,4,2],[2,1,3],[3,5,6]]?','מהו הדטרמיננטה של המטריצה [[1,4,2],[2,1,3],[3,5,6]]?');
INSERT INTO Translation VALUES('cfca8708-73de-4f07-be3d-7ab69a4e3725','What is the determinant of the matrix [[2,3,1],[4,1,5],[6,2,0]]?','מהו הדטרמיננטה של המטריצה [[2,3,1],[4,1,5],[6,2,0]]?');
INSERT INTO Translation VALUES('e7c0b8ce-e03c-40ba-8c89-53bff74528e2','What is the determinant of the matrix [[4,2,-1],[3,5,2],[1,0,6]]?','מהו הדטרמיננטה של המטריצה [[4,2,-1],[3,5,2],[1,0,6]]?');
