INSERT INTO Translation VALUES('87681174-9ddf-4cb4-b79d-dade47e59670','What is the determinant of the matrix [[2,4,6],[1,-1,0],[3,5,7]]?','מהו הדטרמיננטה של המטריצה [[2,4,6],[1,-1,0],[3,5,7]]?');
