INSERT INTO Translation VALUES('6e8bdbda-dffc-43bf-ba78-28fc024ac8b9','Linear Equations','משוואות לינאריות');
INSERT INTO Translation VALUES('4c1dfb25-25a7-4d2c-9d97-a6df46feb3f4','Probability Basics','יסודות ההסתברות');
INSERT INTO Translation VALUES('307b002b-ed58-4612-bd5e-9d189ff11db0','Is x=2 a solution to 3x-6=0','האם x=2 הוא פתרון למשוואה 3x-6=0');
INSERT INTO Translation VALUES('b3a07885-f515-4a33-ac10-5c92695d0172','Is x=4 a solution to 2x+1=9','האם x=4 הוא פתרון למשוואה 2x+1=9');
INSERT INTO Translation VALUES('b84aaec3-5374-460e-abc7-dd26801acc97','Is x=1 a solution to 5x+2=12','האם x=1 הוא פתרון למשוואה 5x+2=12');
INSERT INTO Translation VALUES('9ebf3fd4-4f97-42fb-aef5-a5c133c95c09','Is x=3 a solution to x/2-3=1','האם x=3 הוא פתרון למשוואה x/2-3=1');
INSERT INTO Translation VALUES('4e5741bc-dbe6-4590-913f-9926f6adcfe7','Is x=3 and y=2 a solution to system x+y=5 and x-y=1','האם x=3 ו y=2 הם פתרון למערכת x+y=5 ו x-y=1');
INSERT INTO Translation VALUES('daaefdba-936f-43b0-8fca-e5a0000f7ef2','Is x=1 and y=1 a solution to system 2x+3y=6 and x-y=0','האם x=1 ו y=1 הם פתרון למערכת 2x+3y=6 ו x-y=0');
INSERT INTO Translation VALUES('adb534c9-ed46-4cac-b3a2-3bb5bac43fda','Is x=1 a solution to 7x-4=3','האם x=1 הוא פתרון למשוואה 7x-4=3');
INSERT INTO Translation VALUES('1e25b879-86db-44e8-a04a-00d9dabe0a43','Is x=0 a solution to 4x+5=5','האם x=0 הוא פתרון למשוואה 4x+5=5');
INSERT INTO Translation VALUES('c517c697-0854-4307-931b-0d4d24e3f568','Is x=1 and y=0 a solution to system x+y=1 and 2x+2y=2','האם x=1 ו y=0 הם פתרון למערכת x+y=1 ו 2x+2y=2');
INSERT INTO Translation VALUES('c4547ab8-2327-48e1-86ca-ece2f0df0e8d','Is x=1/3 a solution to 6x-2=1','האם x=1/3 הוא פתרון למשוואה 6x-2=1');
INSERT INTO Translation VALUES('8d3a08b5-5065-4cb7-8630-cc2f6cc13b53','In a fair coin toss is probability of heads 0.5','בהטלת מטבע הוגנת האם ההסתברות לצד עץ היא 0.5');
INSERT INTO Translation VALUES('9e6be0ca-8822-433b-9434-25faebe6ff2a','Is probability of rolling a 7 on a six sided die 1/6','האם ההסתברות לגלגל 7 בקובייה בעלת שש פאות היא 1/6');
INSERT INTO Translation VALUES('7bcb583d-015a-48bd-974f-d7ad92258dca','For two independent events each with probability 0.5 is probability that both occur 0.25','עבור שני אירועים בלתי תלויים שכל אחד בעל הסתברות 0.5 האם ההסתברות ששניהם יקרו היא 0.25');
INSERT INTO Translation VALUES('742b4b5c-01c1-4429-9956-2cb32f0171f6','Is probability of drawing an ace from a standard deck 1/13','האם ההסתברות לשלוף אס מחפיסת קלפים רגילה היא 1/13');
INSERT INTO Translation VALUES('55331a85-439b-4bd0-ac2e-81cb5bc530f2','Are events with probabilities 0.3 and 0.8 always mutually exclusive','האם אירועים בעלי הסתברויות 0.3 ו 0.8 תמיד זרים');
INSERT INTO Translation VALUES('8bae3b74-c8c6-45ae-8c81-1165321012e0','Is expected value of a fair six sided die 3.5','האם התוחלת של קובייה הוגנת בעלת שש פאות היא 3.5');
INSERT INTO Translation VALUES('b3558a47-7c4b-42a7-a82e-872531ede471','Is variance of a fair six sided die 35/12','האם השונות של קובייה הוגנת בעלת שש פאות היא 35/12');
INSERT INTO Translation VALUES('30e153ce-be8a-4999-83db-08491ca78a16','Is probability of at least one tail in two fair coin tosses 0.75','האם ההסתברות לפחות פלי אחד בשתי הטלות מטבע הוגנות היא 0.75');
INSERT INTO Translation VALUES('f9aa190e-6d9e-4c57-aa90-f40c605d7863','Is probability that a randomly chosen day of the week is weekend 2/7','האם ההסתברות שיום בשבוע הנבחר באקראי הוא סוף שבוע היא 2/7');
INSERT INTO Translation VALUES('98d14525-2829-493d-ba8b-7a3c3981deb9','If event A has probability 0.4 is probability of its complement 0.7','אם לאירוע A הסתברות 0.4 האם להשלמתו הסתברות 0.7');
INSERT INTO Translation VALUES('53ee56a0-ce58-498e-9eab-5d4b5979655b','Does geometric series sum from n=0 of (1/2)^n converge to 2','האם הטור הגאומטרי Σ(1/2)^n מ n=0 מתכנס ל 2');
INSERT INTO Translation VALUES('4629eb56-9988-4784-9527-f01cc8b2b0a8','Is the series Σ 1/n convergent','האם הטור Σ 1/n מתכנס');
INSERT INTO Translation VALUES('c9848308-6852-4a3c-ab16-649fae324e55','Does the sequence a_n=1/n converge to 0','האם הסדרה a_n=1/n מתכנסת ל 0');
INSERT INTO Translation VALUES('fdeed27d-2ead-4743-b772-545a7585c2ab','Is the series Σ(-1)^n convergent','האם הטור Σ(-1)^n מתכנס');
INSERT INTO Translation VALUES('af2d2a04-bf10-4cad-bbd1-8383ff2bd981','Is the sequence a_n=n^2 bounded','האם הסדרה a_n=n^2 חסומה');
INSERT INTO Translation VALUES('bb6e2d5d-ed1e-46b5-a016-d1a1b21053eb','Does the series Σ1/n^2 converge','האם הטור Σ1/n^2 מתכנס');
INSERT INTO Translation VALUES('8a8a4611-353d-4d9f-a19c-674dd54c68b8','Is limit of sequence (1+1/n)^n equal to e','האם הגבול של הסדרה (1+1/n)^n שווה ל e');
INSERT INTO Translation VALUES('f8318255-f2f3-4c00-b628-1ef1371a2376','Does the series Σ(-1)^n/n converge','האם הטור Σ(-1)^n/n מתכנס');
INSERT INTO Translation VALUES('d8014943-6a36-4908-9aca-2923cf28452e','Is the sequence a_n=(-1)^n bounded','האם הסדרה a_n=(-1)^n חסומה');
INSERT INTO Translation VALUES('a98199ac-0f21-4702-bfd4-95fc2667313a','Does a geometric series with ratio 2 converge','האם טור גאומטרי בעל מנה 2 מתכנס');
INSERT INTO Translation VALUES('5dc13d54-9817-451b-a07f-1155c8e3bc26','Implicit Function','פונקציה סמויה');
INSERT INTO Translation VALUES('7a1446e4-14e7-4406-be95-3e291f8e3b6f','Implicit Function Theorem','משפט הפונקציה הסמויה');
INSERT INTO Translation VALUES('7bf24157-3dcb-404a-8a5c-f26112eed59b','Does the equation x² + y² = 1 define y implicitly as a function of x near (0,1)','האם המשוואה x² + y² = 1 מגדירה את y כפונקציה סמויה של x בסביבת (0,1)');
INSERT INTO Translation VALUES('2d72a787-0e33-4f8e-8f22-9f7b7b78c008','Is the equation x² + y² = -1 solvable for real y near x=0','האם המשוואה x² + y² = -1 ניתנת לפתרון עבור y ממשי בסביבת x=0');
INSERT INTO Translation VALUES('85ffb5f4-01ce-4f4a-b7d4-f24d5e4f331f','Does the Implicit Function Theorem require ∂F/∂y ≠ 0 at the point','האם משפט הפונקציה הסמויה דורש שהנגזרת החלקית ∂F/∂y תהיה שונה מאפס בנקודה');
INSERT INTO Translation VALUES('45f661e3-7c7f-4407-b41e-de05633e33f5','For F(x,y)=xy, is y uniquely an implicit function of x near (0,0)','האם עבור F(x,y)=xy מתקבל ש‑y היא פונקציה סמויה יחידה של x בסביבת (0,0)');
INSERT INTO Translation VALUES('c8c4c26c-4963-430a-a3ce-5cfb8bb5175c','Does y - x³ = 0 define a smooth implicit function y(x)','האם y - x³ = 0 מגדירה פונקציה סמויה חלקה y(x)');
INSERT INTO Translation VALUES('f5c0953f-12fc-4a54-8c6f-9b585ee16089','Is y implicitly differentiable from x² + y² - 1 = 0 near (0,1)','האם y נגזרת בסתר מן המשוואה x² + y² - 1 = 0 בסביבת (0,1)');
INSERT INTO Translation VALUES('c8db2563-fc3b-424d-aee8-85dbf55c4870','Can y² = x define a differentiable function near x=0','האם y² = x יכולה להגדיר פונקציה נגזרת בסביבת x=0');
INSERT INTO Translation VALUES('5f506319-fea0-4734-89df-3b38fde94097','If ∂F/∂y = 0 at a point, can the Implicit Function Theorem still guarantee a solution','אם ∂F/∂y = 0 בנקודה האם משפט הפונקציה הסמויה עדיין מבטיח פתרון');
INSERT INTO Translation VALUES('01ab283c-1c72-413c-bb51-fe35e72f770a','Are implicit functions always defined on an entire domain','האם פונקציות סמויות מוגדרות תמיד על כל התחום');
INSERT INTO Translation VALUES('d4540e69-ff6a-4e8c-af32-70aaafdc6db7','Does the theorem apply to F(x,y)=y - sin x at (0,0)','האם המשפט חל על F(x,y)=y - sin x בנקודה (0,0)');
INSERT INTO Translation VALUES('2f243a6e-e9b6-402c-9dc8-877329a4552c','For eʸ + x = 0, is y an implicit function near x=-1','האם מהמשוואה eʸ + x = 0 מתקבל ש‑y היא פונקציה סמויה בסביבת x=-1');
INSERT INTO Translation VALUES('99dca6c8-4110-4942-abb4-7ed9a90fc0f7','Does y³ + y + x = 0 define y(x) implicitly near x=0','האם y³ + y + x = 0 מגדירה את y(x) בסתר בסביבת x=0');
INSERT INTO Translation VALUES('70da8c16-ccea-4be6-a66f-2a2f20dfe11f','In F(x,y)=y² + x², is ∂F/∂y at (0,0) nonzero','האם ב‑F(x,y)=y² + x² הנגזרת החלקית ∂F/∂y בנקודה (0,0) שונה מאפס');
INSERT INTO Translation VALUES('5bfed97c-42a6-47f0-a227-d65c6ca820b8','Can implicit differentiation find dy/dx from x² + y² = 4','האם ניתן להשתמש בגזירה בסתר כדי למצוא dy/dx מן המשוואה x² + y² = 4');
INSERT INTO Translation VALUES('8bf1dbd5-ded2-4fd1-ae74-9dbc568bbeb8','Is dy/dx for x² + y² = 4 equal to -x/y','האם dy/dx עבור x² + y² = 4 שווה ל־-x/y');
INSERT INTO Translation VALUES('76359b63-9dff-4951-a709-1fa9f1da15cd','For xy + y = 0, is dy/dx at (0,0) defined','האם עבור xy + y = 0 מוגדר dy/dx בנקודה (0,0)');
INSERT INTO Translation VALUES('f8dd7b41-e765-4642-a93e-3a6581f1e951','Does y = cos x represent an implicit function','האם y = cos x מייצגת פונקציה סמויה');
INSERT INTO Translation VALUES('42ab3dce-9ff9-48bf-b493-0a65134ddfe5','Does every implicit function require solving a polynomial equation','האם כל פונקציה סמויה דורשת פתרון של משוואה פולינומית');
INSERT INTO Translation VALUES('0e7f7b9b-8cab-4777-af79-cd0631de5bdf','Is the Implicit Function Theorem valid in ℝⁿ for n greater than 2','האם משפט הפונקציה הסמויה תקף ב‑ℝⁿ עבור n גדול מ‑2');
INSERT INTO Translation VALUES('91abfa9b-abcc-4d9d-83f5-a757b29d1dce','Can the theorem be used to solve for multiple variables simultaneously','האם ניתן להשתמש במשפט כדי לפתור עבור כמה משתנים בו‑זמנית');
INSERT INTO Translation VALUES('97ffc6c0-fea5-4331-94cd-20208fa3e1b3','Is a nonzero Jacobian determinant required for the multivariable theorem','האם דרוש דטרמיננטה לא אפסית של היעקוביאן עבור המשפט הרב משתני');
INSERT INTO Translation VALUES('1a7c9510-7498-4c83-b135-be80383a9933','Does F(x,y)=y² - x have a differentiable solution y(x) near (0,0)','האם ל‑F(x,y)=y² - x יש פתרון y(x) נגזר בסביבת (0,0)');
INSERT INTO Translation VALUES('96c2ed26-f52c-4882-b069-f1cdd702351c','Does ln(x) + y = 0 require implicit differentiation to find dy/dx','האם ln(x) + y = 0 מחייב גזירה בסתר כדי למצוא dy/dx');
INSERT INTO Translation VALUES('df699b8f-89e5-4120-b1b7-231194efda99','Does the Implicit Function Theorem guarantee a unique implicit function','האם משפט הפונקציה הסמויה מבטיח פונקציה סמויה יחידה');
INSERT INTO Translation VALUES('377643db-0732-4680-9d7f-9fcd3eb21049','For x + y + z = 0, can z be written as an implicit function of x and y','האם מן המשוואה x + y + z = 0 ניתן לכתוב את z כפונקציה סמויה של x ו‑y');
INSERT INTO Translation VALUES('7fd20a5e-4ca6-4084-842d-d450283668b8','Does x² + y² = 0 define y as a function of x near x=0','האם x² + y² = 0 מגדירה את y כפונקציה של x בסביבת x=0');
INSERT INTO Translation VALUES('f849a09a-d365-4d31-bc5f-a847a105bf0b','In xy = 1, is dy/dx equal to -y/x','האם ב‑xy = 1 מתקבל dy/dx = -y/x');
INSERT INTO Translation VALUES('6253f99d-4672-4816-960b-5013c7840a50','For y² + x y + x² = 0, is dy/dx defined at (0,0)','האם עבור y² + x y + x² = 0 מוגדר dy/dx בנקודה (0,0)');
INSERT INTO Translation VALUES('b8f34e32-e2fa-414e-9ec4-87f29b007839','Does the theorem ensure existence of derivatives for implicit functions','האם המשפט מבטיח קיום נגזרות לפונקציות סמויות');
INSERT INTO Translation VALUES('4f6d44db-249e-48de-a23a-507f14b9d354','If F(x,y)=0 defines y(x), is dy/dx equal to -F_x/F_y when F_y ≠ 0','אם F(x,y)=0 מגדירה את y(x) האם dy/dx שווה ל־-F_x/F_y כאשר F_y ≠ 0');
INSERT INTO Translation VALUES('c6871315-ca77-4b15-b894-58a0b88e74e8','Vector Spaces','מרחבים וקטוריים');
INSERT INTO Translation VALUES('2f476947-15fa-4c9c-9f27-90a640ed9f21','Eigenvalues and Eigenvectors','ערכים עצמיים ווקטורים עצמיים');
INSERT INTO Translation VALUES('fe824c71-d84b-4ffb-a721-510283887674','Diagonalization','דיאגונליזציה');
INSERT INTO Translation VALUES('e90a8ca3-1918-4cd3-a96f-6ef2896dc020','Is the set of all linear combinations of given vectors called their span','האם קבוצת כל הצירופים הלינאריים של וקטורים נתונים נקראת המרחב שהם פורשים');
INSERT INTO Translation VALUES('770c542e-e56e-4822-8c31-4fd1f1563355','Does every vector space have a basis','האם לכל מרחב וקטורי יש בסיס');
INSERT INTO Translation VALUES('c97bb73c-5d05-407d-85a9-61994c46bcc3','Is the zero vector required in every subspace','האם הווקטור האפס נדרש בכל תת־מרחב');
INSERT INTO Translation VALUES('032b3716-0912-4800-b1b5-b9a8d08dbcf3','Can linearly dependent vectors form a basis','האם וקטורים תלויים לינארית יכולים ליצור בסיס');
INSERT INTO Translation VALUES('fb793e45-1e34-499b-a568-ded5beb466dc','Is the dimension of ℝ^3 equal to 3','האם הממד של ℝ^3 שווה ל־3');
INSERT INTO Translation VALUES('58901428-472f-40e9-996b-ca45302894db','Are the standard basis vectors in ℝ^2 linearly independent','האם וקטורי הבסיס הסטנדרטיים ב־ℝ^2 הם בלתי תלויים לינארית');
INSERT INTO Translation VALUES('c8ec3add-8f51-484c-b47b-f51323be523f','Does adding a vector to a basis always keep it a basis','האם הוספת וקטור לבסיס תמיד משאירה אותו בסיס');
INSERT INTO Translation VALUES('a7db6a88-ff8d-4917-ace1-a376a8c97d42','Is the empty set a basis of the zero vector space','האם הקבוצה הריקה היא בסיס של מרחב הווקטורים האפסי');
INSERT INTO Translation VALUES('2b903c79-1786-451f-a5ad-52591230b567','Are two different bases of a vector space always of the same size','האם שני בסיסים שונים של מרחב וקטורי הם תמיד באותו גודל');
INSERT INTO Translation VALUES('565f4f02-22dc-49e8-8b55-9ecf7988d254','Can a vector space over ℝ have an infinite basis','האם למרחב וקטורי מעל ℝ יכול להיות בסיס אינסופי');
INSERT INTO Translation VALUES('b6935507-f538-48f9-95bd-830923a12cfd','Is λ an eigenvalue if there exists a nonzero vector v such that Av = λv','האם λ הוא ערך עצמי אם קיים וקטור שאינו אפס כך ש־Av = λv');
INSERT INTO Translation VALUES('709285d5-4d1e-48d8-bf2c-67b79f6ebd2e','Can a matrix have more eigenvectors than eigenvalues','האם למטריצה יכולים להיות יותר וקטורים עצמיים מאשר ערכים עצמיים');
INSERT INTO Translation VALUES('64604d61-a769-48ad-b6dc-2a720b0c8741','Are eigenvectors corresponding to distinct eigenvalues always linearly independent','האם וקטורים עצמיים השייכים לערכים עצמיים שונים תמיד בלתי תלויים לינארית');
INSERT INTO Translation VALUES('3e03bb09-da62-44cc-9e6d-9fd176b18a2c','Is the determinant of A - λI equal to zero for an eigenvalue λ','האם הדטרמיננטה של A - λI שווה לאפס עבור ערך עצמי λ');
INSERT INTO Translation VALUES('0c00cf37-667d-4b05-9ddd-82916562e13f','Can a real matrix have complex eigenvalues','האם למטריצה ממשית יכולים להיות ערכים עצמיים מרוכבים');
INSERT INTO Translation VALUES('13ae2623-d9e9-4bda-a8ac-527341720eee','Is every eigenvector also an eigenvalue','האם כל וקטור עצמי הוא גם ערך עצמי');
INSERT INTO Translation VALUES('cf0ced9c-a271-40f8-a055-7b1ceafc3845','Do eigenvectors corresponding to the same eigenvalue form a subspace','האם וקטורים עצמיים השייכים לאותו ערך עצמי יוצרים תת־מרחב');
INSERT INTO Translation VALUES('551ea0aa-3ca8-42bf-8b9c-8aac63e8d68c','Is the trace of a matrix the product of its eigenvalues','האם עקבת המטריצה היא מכפלת הערכים העצמיים שלה');
INSERT INTO Translation VALUES('511b4088-781e-4f74-8d1a-49df93d20be7','Can a defective matrix be diagonalizable','האם מטריצה דפקטיבית יכולה להיות ניתנת לדיאגונליזציה');
INSERT INTO Translation VALUES('0c08bdf7-617e-4947-b38b-f1803cbdf08b','Is an eigenvalue of A^2 equal to the square of an eigenvalue of A','האם ערך עצמי של A^2 שווה לריבוע ערך עצמי של A');
INSERT INTO Translation VALUES('944c8356-0a34-4cf5-b343-36ec4f54f662','Is a matrix diagonalizable if it has n linearly independent eigenvectors','האם מטריצה ניתנת לדיאגונליזציה אם יש לה n וקטורים עצמיים בלתי תלויים לינארית');
INSERT INTO Translation VALUES('e30be03f-cdbf-4682-a390-11dfcbb34b70','Are all symmetric matrices diagonalizable over ℝ','האם כל המטריצות הסימטריות ניתנות לדיאגונליזציה מעל ℝ');
INSERT INTO Translation VALUES('300a9d3c-d08f-4b8f-b20a-2b41a3873f8e','Can a matrix with a repeated eigenvalue be non-diagonalizable','האם מטריצה עם ערך עצמי חוזר יכולה להיות לא ניתנת לדיאגונליזציה');
INSERT INTO Translation VALUES('a198c112-0a4a-48bf-9328-570015f9cb95','Is diagonalization possible if the minimal polynomial has distinct linear factors','האם דיאגונליזציה אפשרית אם הפולינום המינימלי מתפרק לגורמים לינאריים שונים');
INSERT INTO Translation VALUES('56539258-7920-4bff-8966-b11b25cb33fe','Is every diagonalizable matrix invertible','האם כל מטריצה הניתנת לדיאגונליזציה היא הפיכה');
INSERT INTO Translation VALUES('415f4e11-288e-4cf4-acd3-de241a2fc634','Does a diagonalizable matrix necessarily commute with all matrices','האם מטריצה שניתנת לדיאגונליזציה מתחלפת בהכרח עם כל המטריצות');
INSERT INTO Translation VALUES('9284f0bd-288f-43d4-8175-64d973b92d4a','Can a matrix be diagonalized by a similarity transformation','האם ניתן לדיאגונליזציה של מטריצה באמצעות טרנספורמציית דמיון');
INSERT INTO Translation VALUES('ccb992bc-81f3-4678-87f7-764957fffc6d','Are orthogonal matrices always diagonalizable over ℝ','האם מטריצות אורתוגונליות תמיד ניתנות לדיאגונליזציה מעל ℝ');
INSERT INTO Translation VALUES('ab4f4fff-6fde-4154-8cf7-cc009ced31d5','Is a diagonal matrix already diagonalizable','האם מטריצה אלכסונית היא כבר ניתנת לדיאגונליזציה');
INSERT INTO Translation VALUES('dee66e0f-60b1-40aa-832a-1106870a039c','Does diagonalization simplify computing matrix powers','האם דיאגונליזציה מקלה על חישוב חזקה של מטריצה');
