INSERT INTO Translation VALUES('034754a1-42b1-459f-aa13-690466854c9c','Prove that p ∧ (q ∨ r) ≡ (p ∧ q) ∨ (p ∧ r) using truth tables','הוכיחו שp ∧ (q ∨ r) ≡ (p ∧ q) ∨ (p ∧ r) באמצעות טבלאות אמת');
