INSERT INTO Translation VALUES('0188eaad-3f7c-44ae-b195-170d244756a2','According to the First Fundamental Theorem of Calculus, if F(x) = f(x), then:','לפי המשפט הבסיסי הראשון של החדוא, אם F(x) = f(x), אז:');
INSERT INTO Translation VALUES('b2da7a9a-bc5b-444e-930c-6b3a901295ed','∫ₐᵇ f(x) dx = F(b) - F(a)','∫ₐᵇ f(x) dx = F(b) - F(a)');
