INSERT INTO Translation VALUES('9ae6bbb7-1629-4f07-9288-4a6bb6c14e5a','bₙ is constant','bₙ קבועה');
INSERT INTO Translation VALUES('30fc2810-834d-45cd-b358-bb399e0d47e4','bₙ is bounded but may not converge','bₙ חסומה אבל יכולה לא להתכנס');
INSERT INTO Translation VALUES('56ce08e7-f601-4f61-b196-7817025bd315','A monotone increasing sequence that is bounded above:','סדרה מונוטונית עולה החסומה מלמעלה:');
