INSERT INTO Translation VALUES('c28a8d67-bee2-4dbd-925e-f2490bf69a76','What is the value of the geometric series Σ(1/2)ⁿ for n=0 to ∞?','מהו ערך הטור הגיאומטרי Σ(1/2)ⁿ עבור n=0 עד ∞?');
