INSERT INTO Translation VALUES('f6d56005-c541-4f40-b28f-2b53d8ecd2c1','What is the integration by parts formula?','מה הנוסחה לאינטגרציה בחלקים?');
INSERT INTO Translation VALUES('a8348960-deb9-43ce-aea6-bec2d4bc9ced','∫u dv = uv - ∫v du','∫u dv = uv - ∫v du');
