INSERT INTO Translation VALUES('866e6521-9a20-4777-ad33-138e787c55e2','∫uv dx = u∫v dx - ∫(du/dx ∫v dx)dx','∫uv dx = u∫v dx - ∫(du/dx ∫v dx)dx');
INSERT INTO Translation VALUES('02179747-8a98-4035-953c-c6e5bb3168cf','∫f(g(x))g''(x)dx = ∫f(u)du','∫f(g(x))g''(x)dx = ∫f(u)du');
