INSERT INTO Translation VALUES('160d98fc-f1fd-43bc-b119-7e27e32ad491','Ensuring the degree of numerator is less than denominator','הבטחה שמעלת המונה קטנה ממעלת המכנה');
INSERT INTO Translation VALUES('d49842ff-d857-4cf2-9292-e591bace7ce9','Taking the derivative','נגזרת');
INSERT INTO Translation VALUES('bf68eea2-4ccb-4bd2-adac-1893f2fbc21f','Integration by parts','אינטגרציה בחלקים');
INSERT INTO Translation VALUES('481e1f7d-9558-4857-9815-05dc9bf74f0a','Trigonometric substitution','החלפה טריגונומטרית');
INSERT INTO Translation VALUES('42eb42d2-e454-41a1-b16d-9e5cfe1b789d','The definite integral ∫[a to b] f(x)dx represents:','האינטגרל המוגדר ∫[a to b] f(x)dx מייצג:');
INSERT INTO Translation VALUES('82b7f2b5-d052-40d5-8be2-34a19d989c6e','The signed area between f(x) and the x-axis from a to b','השטח המסומן בין f(x) לציר ה-x מ-a עד b');
