INSERT INTO Translation VALUES('e91f1f8b-a6b5-4f64-851f-470473063d14','f(x) > 0 for all x ≥ a','f(x) > 0 לכל x ≥ a');
INSERT INTO Translation VALUES('da1e1389-cb3a-44c5-9a4a-0eb6d1f13ad2','f(x) is continuous on [a,∞)','f(x) רציפה על [a,∞)');
INSERT INTO Translation VALUES('9ee7a73c-fac5-4194-a5e8-505fc15b5002','For improper integrals of unbounded functions, we have ∫[a to b] f(x)dx where f has a vertical asymptote at:','עבור אינטגרלים לא אמיתיים של פונקציות לא חסומות, יש לנו ∫[a to b] f(x)dx כאשר ל-f יש אסימפטוטה אנכית ב:');
