INSERT INTO Translation VALUES('1c009c5f-923f-44a0-8bdc-43d9132c0d86','For an improper integral ∫[a to b] f(x)dx where f has a discontinuity at x=c ∈ (a,b), we split it into:','עבור אינטגרל לא אמיתי ∫[a to b] f(x)dx כאשר ל-f יש אי-רציפות ב-x=c ∈ (a,b), מפצלים אותו ל:');
INSERT INTO Translation VALUES('994c9e74-8175-43e7-9b14-383b4b133014','∫[a to c] f(x)dx + ∫[c to b] f(x)dx','∫[a to c] f(x)dx + ∫[c to b] f(x)dx');
INSERT INTO Translation VALUES('be8fe15e-30d2-4153-8510-35e72e440b7b','∫[a to c-ε] f(x)dx + ∫[c+ε to b] f(x)dx for small ε > 0','∫[a to c-ε] f(x)dx + ∫[c+ε to b] f(x)dx עבור ε > 0 קטן');
INSERT INTO Translation VALUES('7776deed-d19d-4f90-9b3b-0901cdb9b9a0','Just ∫[a to b] f(x)dx','פשוט ∫[a to b] f(x)dx');
