INSERT INTO Translation VALUES('56b6e5a8-01a8-4ff3-8964-c3407bd7d80a','What is the completion of subsequences in analysis?','מהי השלמת תת-סדרות בניתוח?');
INSERT INTO Translation VALUES('c0ff4217-e6b3-4235-baa1-216818035d7b','A method to extend convergent subsequences to complete sequences','שיטה להרחבת תת-סדרות מתכנסות לסדרות שלמות');
