INSERT INTO Translation VALUES('b559c55c-c9cf-4976-bcd5-2eb5bc2520ca','The integral equals the average value','האינטגרל שווה לערך הממוצע');
INSERT INTO Translation VALUES('80796c8f-575e-4e6e-b220-ba7b79d9570f','All continuous functions have the same integral','לכל הפונקציות הרציפות יש אותו אינטגרל');
INSERT INTO Translation VALUES('a6e5a34b-b4c2-445f-953a-fa9f11325f5c','The derivative equals the integral','הנגזרת שווה לאינטגרל');
