INSERT INTO Translation VALUES('fe84bc7e-7422-4d3c-99f8-d6afe4d84875','All positive series converge','כל הטורים החיוביים מתכנסים');
INSERT INTO Translation VALUES('d80e2175-5eed-4c3a-9557-19af5602ec74','Compare derivatives','השווה נגזרות');
INSERT INTO Translation VALUES('169d95df-25ee-441e-9455-cd244e0cc9f8','What is absolute convergence?','מהי התכנסות מוחלטת?');
INSERT INTO Translation VALUES('0183e56d-ed47-49b5-ae52-d8e0ff5c9898','A series Σa_n converges absolutely if Σ|a_n| converges','טור Σa_n מתכנס במוחלט אם Σ|a_n| מתכנס');
INSERT INTO Translation VALUES('c92f2de4-0139-4d92-8e69-36877f62e70e','A series with only positive terms','טור עם איברים חיוביים בלבד');
INSERT INTO Translation VALUES('21235c01-4dc4-4d6a-aada-a61540f524fb','A series that converges very fast','טור שמתכנס מהר מאוד');
INSERT INTO Translation VALUES('b52e7388-6d9b-46fc-a467-bddb38445d47','A series with infinite terms','טור עם איברים אינסופיים');
INSERT INTO Translation VALUES('11a88b78-62f8-437e-889a-23a5cc23cc21','The ratio test: if lim |a_{n+1}/a_n| = L < 1, then the series converges. True or false?','מבחן היחס: אם lim |a_{n+1}/a_n| = L < 1, אז הטור מתכנס. נכון או לא נכון?');
INSERT INTO Translation VALUES('bbb5934f-bb63-455f-8a70-10bb52656d02','In the root test, if lim sup |a_n|^(1/n) = L, what happens when L < 1?','במבחן השורש, אם lim sup |a_n|^(1/n) = L, מה קורה כאשר L < 1?');
INSERT INTO Translation VALUES('39f90768-6bb1-40db-a44a-1a673f880d46','The series converges absolutely','הטור מתכנס במוחלט');
INSERT INTO Translation VALUES('1aa6d8a3-4dd3-4132-949e-461f010d9f4a','The series diverges','הטור מתבדר');
INSERT INTO Translation VALUES('7cf0d76c-566e-4f48-bfdf-0c0ef21a2466','The test is inconclusive','המבחן לא חד-משמעי');
INSERT INTO Translation VALUES('af7a6866-c4f5-4c95-ba41-bdb528dafa8c','The series oscillates','הטור מתנודד');
