INSERT INTO Translation VALUES('62cbc04e-106f-4997-9104-14fa64532b4a','Rules for geometric proofs','כללים להוכחות גיאומטריות');
INSERT INTO Translation VALUES('94b511bf-3606-4f13-b551-5affed02ac48','Rules for algebraic manipulation','כללים לטיפול אלגברי');
