INSERT INTO Translation VALUES('5385b106-f833-48a5-99e0-c100a61fcf2f','The function has a local maximum','לפונקציה יש מקסימום מקומי');
INSERT INTO Translation VALUES('fc303fd3-5e2d-4afe-bf44-cfbc45a2f082','The function crosses the x-axis','הפונקציה חוצה את ציר ה-x');
