INSERT INTO Translation VALUES('367f2f95-ee28-4858-9185-43e58ad09921','L''Hôpital''s rule can be applied when we have indeterminate forms of type:','ניתן להחיל את חוק לופיטל כאשר יש לנו צורות לא מוגדרות מסוג:');
