INSERT INTO Translation VALUES('e29a4b79-d755-4db9-87d4-8b3ea82a4107','The limit does not exist','הגבול לא קיים');
INSERT INTO Translation VALUES('4b1202d5-7667-4eb9-89ca-bd99aa869641','The limit equals zero','הגבול שווה לאפס');
