INSERT INTO Translation VALUES('eb91d689-a68c-4159-8fb9-d98d3716e47d','If a continuous function on an open interval has only one local extremum, then:','אם לפונקציה רציפה על קטע פתוח יש רק קיצון מקומי אחד, אז:');
