INSERT INTO Translation VALUES('00ad3b1a-54bc-4c2e-a2ce-60e17c17925e','The function is monotonic','הפונקציה מונוטונית');
INSERT INTO Translation VALUES('104dcbc4-cb28-4cd5-b453-7e9504dddeb9','The function is constant','הפונקציה קבועה');
INSERT INTO Translation VALUES('31b2452f-890d-4455-96cf-08fac4d3ceee','The function has no critical points','לפונקציה אין נקודות קריטיות');
INSERT INTO Translation VALUES('d7ae1853-1f2f-45e4-bed0-1fe4830b5c61','This unique extremum property is particularly useful for:','תכונת הקיצון הייחודי שימושית במיוחד עבור:');
INSERT INTO Translation VALUES('0320ce91-ddd8-4e84-a26f-06499bee59ee','Optimization problems where we need to find global minima or maxima','בעיות אופטימיזציה שבהן אנו צריכים למצוא מינימומים או מקסימומים גלובליים');
