INSERT INTO Translation VALUES('ae1afaaa-7221-40e8-aaf2-d20e8306e528','The integration by parts formula is:','הנוסחה לאינטגרציה בחלקים היא:');
INSERT INTO Translation VALUES('523a7073-74bd-4f2d-b66f-582c3672e9b9','∫u dv = uv - ∫v du','∫u dv = uv - ∫v du');
