INSERT INTO Translation VALUES('f695a540-8c11-434e-81bf-fa612f5aebf1','L > 1','L > 1');
INSERT INTO Translation VALUES('f8909d3b-7ed6-4b3c-92a8-3d4097663459','L = 1','L = 1');
INSERT INTO Translation VALUES('2852902d-1ae5-4d5b-9b12-29536045ed18','When the ratio test gives L = 1, the test is inconclusive. True or False?','כאשר מבחן היחס נותן L = 1, המבחן אינו חד-משמעי. נכון או לא נכון?');
