INSERT INTO Translation VALUES('a2d2ea1a-7a44-431f-9852-08790ef1f8e5','The converse of If P then Q is If Q then P. True or False?','ההיפך של אם P אז Q הוא אם Q אז P. נכון או לא נכון?');
