INSERT INTO Translation VALUES('fa07b197-c9cd-46eb-b073-c4139cdb6d9e','A sequence with bounded terms','סדרה עם איברים חסומים');
INSERT INTO Translation VALUES('8702ff99-085b-4b04-ba3f-c198f1d67a5d','A sequence of real numbers only','סדרה של מספרים ממשיים בלבד');
INSERT INTO Translation VALUES('83ea8e94-670d-475d-9fa4-e646c70fae6e','An infinite sequence continues indefinitely','סדרה אינסופית נמשכת ללא הגבלה');
