INSERT INTO Translation VALUES('86f97ac6-9265-40a2-9f8e-c383cb3a1949','Direct integration','אינטגרציה ישירה');
INSERT INTO Translation VALUES('520d03f7-db62-49f1-a2c4-591944a0a86e','Integration by parts','אינטגרציה בחלקים');
INSERT INTO Translation VALUES('192c306e-5c20-4c54-8206-3db5d93b2b22','Substitution only','הצבה בלבד');
INSERT INTO Translation VALUES('44a03be8-725c-4d2f-b8f9-2b474e610d78','Does the integral ∫[0,1] 1/x² dx converge?','האם האינטגרל ∫[0,1] 1/x² dx מתכנס?');
INSERT INTO Translation VALUES('4b6f73f4-232b-491d-ab7b-f732f9e0f2f3','The value of ∫[0,1] 1/√x dx is:','הערך של ∫[0,1] 1/√x dx הוא:');
INSERT INTO Translation VALUES('43990bca-c540-4414-bf34-53b503f5199b','The comparison test for improper integrals states that if 0 ≤ f(x) ≤ g(x) and ∫g(x)dx converges, then ∫f(x)dx converges.','מבחן ההשוואה לאינטגרלים לא אמיתיים קובע שאם 0 ≤ f(x) ≤ g(x) ו-∫g(x)dx מתכנס, אז ∫f(x)dx מתכנס.');
INSERT INTO Translation VALUES('f4d052c6-afc8-47da-a9c8-05224891e801','The logical AND operator (∧) returns true when:','האופרטור הלוגי AND (∧) מחזיר true כאשר:');
INSERT INTO Translation VALUES('235c5988-457f-44b7-a13c-749d15590cac','Both operands are true','שני הפעולה הם true');
INSERT INTO Translation VALUES('9b0cb625-2539-4a33-bbc6-9c9dc30b40d5','At least one operand is true','לפחות פעולה אחד הוא true');
INSERT INTO Translation VALUES('2c20dd82-7f40-426f-8c01-a579553f8232','Exactly one operand is true','בדיוק פעולה אחד הוא true');
INSERT INTO Translation VALUES('d2010d9e-2e79-4b97-9819-07a0fcefba92','No operand is true','אף פעולה אינו true');
INSERT INTO Translation VALUES('d46bb655-8238-4979-aede-fb5c1fb41f7a','The logical OR operator (∨) returns false only when both operands are false.','האופרטור הלוגי OR (∨) מחזיר false רק כאשר שני הפעולה הם false.');
INSERT INTO Translation VALUES('9f9e00f2-bfee-4e33-ae47-0a21a3f881c1','What is the result of NOT(true AND false)?','מה התוצאה של NOT(true AND false)?');
INSERT INTO Translation VALUES('7a2fbdc5-2b31-4ac1-bca2-c218b3d99eb5','The XOR (exclusive OR) operator returns true when:','האופרטור XOR (או בלעדי) מחזיר true כאשר:');
INSERT INTO Translation VALUES('f44bf3a9-b679-4dac-b5a8-672807fbeac8','Exactly one operand is true','בדיוק פעולה אחד הוא true');
INSERT INTO Translation VALUES('315397ce-e6f9-4c38-ba91-9b36ca5c5b65','Both operands are true','שני הפעולה הם true');
INSERT INTO Translation VALUES('5a0323b7-f230-4b88-93fd-8c469eced364','Both operands are false','שני הפעולה הם false');
INSERT INTO Translation VALUES('ad461cdc-8002-450b-a4b6-b3e588157580','At least one operand is true','לפחות פעולה אחד הוא true');
INSERT INTO Translation VALUES('ad0c9338-a68c-41bc-a265-38dce35a53f4','In Boolean logic, true can be represented by 1 and false by 0.','בלוגיקה בוליאנית, true ניתן לייצוג על ידי 1 ו-false על ידי 0.');
INSERT INTO Translation VALUES('1d172391-95e4-4e31-8533-ff57d52d9404','Truth values in classical logic are:','ערכי האמת בלוגיקה קלאסית הם:');
INSERT INTO Translation VALUES('9fa87598-8cc5-44c2-b63d-39fa33d522cc','True and False only','True ו-False בלבד');
INSERT INTO Translation VALUES('f3118b61-9f6f-486c-851b-f3622fdcc2f5','True, False, and Unknown','True, False, ו-Unknown');
INSERT INTO Translation VALUES('97d968e2-57c1-40f6-80f3-795f79df57a8','Any real number','כל מספר ממשי');
INSERT INTO Translation VALUES('bb1258b4-1851-4ac7-84f0-9d7d03847f83','0, 1, 2, 3, ...','0, 1, 2, 3, ...');
INSERT INTO Translation VALUES('24a08177-9775-4d03-8983-a3ff2ed457d2','A proposition can have both true and false values simultaneously in classical logic.','הצעה יכולה להיות בעלת ערכי true ו-false בו זמנית בלוגיקה קלאסית.');
INSERT INTO Translation VALUES('567d03b3-9401-40e2-a13f-f014260e75ce','The law of excluded middle states that every proposition is either true or false.','חוק השלישי הנפסל קובע שכל הצעה היא או true או false.');
INSERT INTO Translation VALUES('ad1fd59b-f033-4bc6-9158-4b5893ff67ae','A NAND gate outputs false only when:','שער NAND מוציא false רק כאשר:');
INSERT INTO Translation VALUES('104382bf-3f30-46dd-9ec8-caf9b9bdd19b','Both inputs are true','שני הכניסות הם true');
INSERT INTO Translation VALUES('487c2cd5-0b95-4612-a43c-80a3440d0046','Both inputs are false','שני הכניסות הם false');
INSERT INTO Translation VALUES('6d4c39a3-f3de-4186-b88a-90880f159648','At least one input is true','לפחות כניסה אחת היא true');
INSERT INTO Translation VALUES('7dd55165-e0e0-490c-9382-30e4c0066e50','Exactly one input is true','בדיוק כניסה אחת היא true');
INSERT INTO Translation VALUES('209c2000-3086-40ef-9180-fd1e5f2f0327','An OR gate outputs true when at least one input is true.','שער OR מוציא true כאשר לפחות כניסה אחת היא true.');
INSERT INTO Translation VALUES('2395a91e-7505-4cb6-9714-cd5604bd4b14','What is the output of an AND gate when inputs are (1,0)?','מה הפלט של שער AND כאשר הכניסות הן (1,0)?');
INSERT INTO Translation VALUES('2373ec0d-3244-41a3-b63f-c6e03b241c43','A NOR gate is equivalent to an OR gate followed by a NOT gate.','שער NOR שווה ערך לשער OR ואחריו שער NOT.');
INSERT INTO Translation VALUES('763bfc97-b1cd-40cb-a4a4-6e083ca6f6fe','The conditional statement P → Q is false only when:','המשפט התנאי P → Q הוא false רק כאשר:');
INSERT INTO Translation VALUES('4a24b50e-9573-400f-9b59-4af057209296','P is true and Q is false','P הוא true ו-Q הוא false');
INSERT INTO Translation VALUES('3bee1242-a918-4aef-a163-2c7cff9b5919','P is false and Q is true','P הוא false ו-Q הוא true');
INSERT INTO Translation VALUES('0d10feda-ee56-4ba4-a43c-eee3ead5f69c','Both P and Q are false','גם P וגם Q הם false');
INSERT INTO Translation VALUES('93e591c1-7946-49f3-b669-17524d357ab1','Both P and Q are true','גם P וגם Q הם true');
INSERT INTO Translation VALUES('d7e8ba60-1242-4daf-8217-0cb959fbce45','The biconditional P ↔ Q is true when P and Q have the same truth value.','הדו-תנאי P ↔ Q הוא true כאשר ל-P ול-Q יש אותו ערך אמת.');
INSERT INTO Translation VALUES('fec3d469-6d5f-43ab-a5a5-07299177e28a','Which two statements are logically equivalent?','אילו שני הצהרות הן שקולות לוגית?');
INSERT INTO Translation VALUES('7f33262a-8670-44f8-8bef-8745a931cb74','P → Q and ¬Q → ¬P','P → Q ו-¬Q → ¬P');
INSERT INTO Translation VALUES('876ced18-63c6-4958-9fe0-3e2b9ef776fa','P ∧ Q and P ∨ Q','P ∧ Q ו-P ∨ Q');
INSERT INTO Translation VALUES('a880a532-9dc2-4ff9-89dd-1a8faef96714','The statement ¬(P ∧ Q) is equivalent to:','הצהרה ¬(P ∧ Q) שקולה ל:');
INSERT INTO Translation VALUES('ce183be8-ebea-4617-b88c-c3ba05c5efec','¬P ∨ ¬Q','¬P ∨ ¬Q');
INSERT INTO Translation VALUES('353e920f-44e1-44c4-bb46-9d8e52eadeb1','¬P ∧ ¬Q','¬P ∧ ¬Q');
INSERT INTO Translation VALUES('50b77fbf-1246-4a84-b514-10eeed671e4b','Which two statements are logically equivalent?','אילו שני הצהרות הן שקולות לוגית?');
INSERT INTO Translation VALUES('d25ee507-8140-4aef-9678-c68ad661137a','P → Q and ¬Q → ¬P','P → Q ו-¬Q → ¬P');
INSERT INTO Translation VALUES('23a63d04-28e7-460c-96a4-a8d31fa7ee1a','P ∧ Q and P ∨ Q','P ∧ Q ו-P ∨ Q');
INSERT INTO Translation VALUES('9e9eafec-1f7f-4576-8b70-59beca993ec7','P → Q and Q → P','P → Q ו-Q → P');
INSERT INTO Translation VALUES('e467ac46-b6c8-4662-999a-131304548178','The statement ¬(P ∧ Q) is equivalent to:','הצהרה ¬(P ∧ Q) שקולה ל:');
INSERT INTO Translation VALUES('3be7b264-e4dd-4274-a75e-9fea22588466','¬P ∨ ¬Q','¬P ∨ ¬Q');
INSERT INTO Translation VALUES('bc407169-4f6f-4351-a32c-b8d649e60473','¬P ∧ ¬Q','¬P ∧ ¬Q');
INSERT INTO Translation VALUES('946f7b61-1e8e-4fc6-acc4-ad6b537d53fc','P ∨ Q','P ∨ Q');
INSERT INTO Translation VALUES('2412fb65-ec05-4694-b132-af43cee9f3f4','Is (P → Q) ∧ (Q → R) → (P → R) a tautology?','האם (P → Q) ∧ (Q → R) → (P → R) היא טאוטולוגיה?');
INSERT INTO Translation VALUES('8688d9c3-e030-4bbc-8a06-a46d16194c40','The double negation ¬¬P is equivalent to:','השלילה הכפולה ¬¬P שקולה ל:');
INSERT INTO Translation VALUES('addf4728-2667-48d3-abe0-d9dff4f11f33','P','P');
INSERT INTO Translation VALUES('b7db471d-0113-4f96-94b7-3434a26079ab','¬P','¬P');
INSERT INTO Translation VALUES('b698278c-8555-42be-897f-6c9979c3d609','P ∨ ¬P','P ∨ ¬P');
INSERT INTO Translation VALUES('29fb16ea-ef07-4ee1-b585-271435aab004','P ↔ Q is equivalent to:','P ↔ Q שקול ל:');
INSERT INTO Translation VALUES('1849b78e-9e7b-4dbc-a5c6-951861626468','(P → Q) ∧ (Q → P)','(P → Q) ∧ (Q → P)');
INSERT INTO Translation VALUES('7f49eed0-234f-43db-964a-6a69103efd7a','(P → Q) ∨ (Q → P)','(P → Q) ∨ (Q → P)');
INSERT INTO Translation VALUES('4c2faccc-1ff6-420b-a2bb-336b43d7ed5b','P ∧ Q','P ∧ Q');
INSERT INTO Translation VALUES('9080f973-5d64-4498-b4a3-b192e839278b','Which distributive law is correct?','איזה חוק חלוקה נכון?');
INSERT INTO Translation VALUES('79db7e77-cf98-40a8-9e99-bbc488bf9be9','P ∨ (Q ∧ R) ≡ (P ∨ Q) ∧ (P ∨ R)','P ∨ (Q ∧ R) ≡ (P ∨ Q) ∧ (P ∨ R)');
