INSERT INTO Translation VALUES('a28d974d-7384-4f5e-ab10-543bffa6fcc7','Is P ∧ (P → Q) → Q a valid argument form?','האם P ∧ (P → Q) → Q היא צורת ויכוח לוגית תקפה?');
INSERT INTO Translation VALUES('ec5762ca-8412-4722-bcdd-2128792b98dd','De Morgan law states that ¬(P ∨ Q) ≡','חוק דה מורגן קובע ש-¬(P ∨ Q) ≡');
