INSERT INTO Translation VALUES('fc319ba6-f31d-4ad0-852a-d6b23cb172fa','Are generating functions useful for solving recurrence relations?','האם פונקציות מולידות שימושיות לפתרון יחסי נשנות?');
INSERT INTO Translation VALUES('6d690f8e-4740-4f26-b6b2-a8440254cc36','The coefficient of x^n in (1+x)^m is:','המקדם של x^n ב-(1+x)^m הוא:');
