INSERT INTO Translation VALUES('ac67b8d3-9ec8-4a1b-8efe-2b4207da79e9','What is the generating function for the sequence 0, 1, 2, 3, 4, ...?','מה הפונקציה המולידה לסדרה 0, 1, 2, 3, 4, ...?');
