INSERT INTO Translation VALUES('8361bc41-3c96-4c19-8fc0-82d232eb893b','f(x) = sin(x)','f(x) = sin(x)');
INSERT INTO Translation VALUES('1576d431-0262-4fa6-a36d-302a901b1908','At a vertical tangent, the derivative approaches what value?','במשיק אנכי, הנגזרת שואפת לאיזה ערך?');
