INSERT INTO Translation VALUES('7ad6b730-a67e-4b73-96cc-9a8885d67f30','Does not exist','לא קיים');
INSERT INTO Translation VALUES('bac7d452-acc7-4f73-b72b-4ec6ff026175','All continuous functions are differentiable.','כל הפונקציות הרציפות הן גזירות.');
INSERT INTO Translation VALUES('e80378f0-80df-4f9c-aadb-8bfefaacc6b4','Which function has a vertical tangent at x = 0?','איזה פונקציה בעלת משיק אנכי ב x = 0?');
INSERT INTO Translation VALUES('9e9f0aeb-bcef-44ea-b104-8647e75032ff','f(x) = x^(1/3)','f(x) = x^(1/3)');
INSERT INTO Translation VALUES('20e14f60-6f01-4580-bad1-987ae43160ae','f(x) = x^2','f(x) = x^2');
INSERT INTO Translation VALUES('b5166951-cacc-4534-8150-0c2675192562','f(x) = |x|','f(x) = |x|');
INSERT INTO Translation VALUES('8ae4172b-2c2f-40fc-b01e-a5f582a9e964','f(x) = x','f(x) = x');
INSERT INTO Translation VALUES('6c6d6a84-c1b4-4073-b1de-6ca04ae7c265','At a corner, the left and right derivatives exist but are different.','בפינה, הנגזרות השמאלית והימנית קיימות אך שונות.');
INSERT INTO Translation VALUES('1bab5bba-2a6d-4930-ad99-3faa1cdc33ae','How many types of non-differentiability are commonly studied?','כמה סוגים של אי-גזירות נלמדים בדרך כלל?');
INSERT INTO Translation VALUES('910131b4-2240-4794-aa15-0bc211744d3b','Discontinuity always causes non-differentiability.','אי-רציפות תמיד גורמת לאי-גזירות.');
INSERT INTO Translation VALUES('ea55141b-5856-4cbe-b501-0c83d9e599d9','Which type of point has one-sided derivatives that are both infinite?','איזה סוג של נקודה בעלת נגזרות חד-צדדיות שהן שתיהן אינסופיות?');
