INSERT INTO Translation VALUES('4a3d2af3-e539-4805-884e-892350a187c2','Corner','פינה');
INSERT INTO Translation VALUES('30d2e8a5-bdeb-40f9-82b2-d4ca582ff18d','Vertical tangent','משיק אנכי');
INSERT INTO Translation VALUES('262ae699-0ef8-400b-ba4b-d0a25b63e385','Removable discontinuity','אי-רציפות מעילה');
INSERT INTO Translation VALUES('d91516aa-89dd-472c-978e-72c8f0305e9c','The function f(x) = |x - 1| has a corner at x = 1.','לפונקציה f(x) = |x - 1| יש פינה ב x = 1.');
INSERT INTO Translation VALUES('4611ef0a-c307-4dd9-8722-386c065cb97b','What characterizes a jump discontinuity in terms of differentiability?','מה מאפיין אי-רציפות קפיצה במונחי גזירות?');
INSERT INTO Translation VALUES('1fbcd3d2-88e7-4c33-b5df-e2788060ec5b','The function is not differentiable at that point','הפונקציה אינה גזירה באותה נקודה');
INSERT INTO Translation VALUES('16eb7aae-dd20-4247-9959-358f5f73f6d2','The derivative exists but is zero','הנגזרת קיימת אך היא אפס');
INSERT INTO Translation VALUES('e0707200-1fef-4813-ac4f-4af31c4fee81','The derivative is infinite','הנגזרת אינסופית');
