INSERT INTO Translation VALUES('1f0825a8-b02a-41db-b24b-5ea2de227a0a','Oscillatory behavior near a point can cause non-differentiability.','התנהגות תנודתית ליד נקודה יכולה לגרום לאי-גזירות.');
INSERT INTO Translation VALUES('d0c3a9d0-47a8-461a-adcc-ac37188051d2','At which point is the function f(x) = (x-1)² + |x-1| not differentiable?','באיזה נקודה הפונקציה f(x) = (x-1)² + |x-1| אינה גזירה?');
INSERT INTO Translation VALUES('0f29f8bd-0b4b-4a4b-a28d-7b4ec7887eab','A cusp point is characterized by:','נקודת קודד מאופיינת על ידי:');
INSERT INTO Translation VALUES('46722e32-ad7b-45c8-bc06-db1b5eb4a791','Both one-sided derivatives are infinite with opposite signs','שתי הנגזרות החד-צדדיות אינסופיות עם סימנים הפוכים');
INSERT INTO Translation VALUES('0ab2c28b-f01a-4fdb-9740-1d982fb6896a','Both one-sided derivatives are finite but different','שתי הנגזרות החד-צדדיות סופיות אך שונות');
