INSERT INTO Translation VALUES('8a591075-7509-4eba-acdd-3ed417e719b3','The function has a horizontal tangent','לפונקציה יש משיק אופקי');
INSERT INTO Translation VALUES('c955ddcb-e7e8-4478-a9f5-c3d977799a6c','When using implicit differentiation, we differentiate both sides of an equation with respect to:','בעת שימוש בגזירה מרומזת, אנו גוזרים את שני צדדי המשוואה ביחס ל:');
INSERT INTO Translation VALUES('af918a00-0821-454e-9a2d-0b83e379d985','The independent variable (usually x)','המשתנה הבלתי תלוי (בדרך כלל x)');
INSERT INTO Translation VALUES('4544426a-74de-45cf-b9b0-2eefe6b2331f','The dependent variable (usually y)','המשתנה התלוי (בדרך כלל y)');
INSERT INTO Translation VALUES('e57bd958-b2d9-4f04-bbfa-8afbaf895471','Both variables equally','שני המשתנים באופן שווה');
INSERT INTO Translation VALUES('f34777c4-14dd-4ab7-a402-d8cef94770fc','Any variable we choose','כל משתנה שנבחר');
INSERT INTO Translation VALUES('edae5aef-a865-41c2-a524-e1c206d49b37','In implicit differentiation, d/dx[y²] equals 2y⋅dy/dx.','בגזירה מרומזת, d/dx[y²] שווה ל2y⋅dy/dx.');
