INSERT INTO Translation VALUES('3dc7df4d-b1fc-4f93-9848-6364a3775f18','Implicit differentiation is only used when y cannot be expressed explicitly in terms of x.','גזירה מרומזת משמשת רק כאשר y לא יכול להתבטא במפורש במונחי x.');
