INSERT INTO Translation VALUES('0951f860-61d4-4665-9566-49cafa996153','3x²/3y²','3x²/3y²');
INSERT INTO Translation VALUES('d04ccaf8-89b5-4186-b6c8-a91fe15cbf25','When using implicit differentiation, we always solve for dy/dx at the end.','כאשר משתמשים בגזירה מרומזת, אנו תמיד פותרים עבור dy/dx בסוף.');
