INSERT INTO Translation VALUES('a5357f4e-a465-401d-a57e-1295fd4af2df','b/a','b/a');
INSERT INTO Translation VALUES('f11c02ac-429f-402b-8974-9208c2be441e','In implicit differentiation, we treat y as a function of x.','בגזירה מרומזת, אנו מתייחסים ל-y כפונקציה של x.');
INSERT INTO Translation VALUES('33cda958-4fd1-4ce0-80ee-abd5a8ca73b7','Find d²y/dx² for x² + y² = 1 at the point where dy/dx = -x/y:','מצא d²y/dx² עבור x² + y² = 1 בנקודה שבה dy/dx = -x/y:');
