INSERT INTO Translation VALUES('a55e4706-099d-4299-9602-97062d224926','1/x³','1/x³');
INSERT INTO Translation VALUES('25187293-a557-46e0-b945-0b21850e0f25','Implicit differentiation can be used to find higher-order derivatives.','גזירה מרומזת יכולה לשמש למציאת נגזרות מסדר גבוה יותר.');
INSERT INTO Translation VALUES('27359c50-32bd-4d41-89eb-6d6fcb3331e7','For y = sin⁻¹(x), using implicit differentiation gives dy/dx = ?','עבור y = sin⁻¹(x), שימוש בגזירה מרומזת נותן dy/dx = ?');
INSERT INTO Translation VALUES('b278a940-9e62-4f21-bf45-ed7fc0d4f72f','1/√(1-x²)','1/√(1-x²)');
