INSERT INTO Translation VALUES('4836b6d9-4aee-4793-9b85-3bd8a175dff7','1/(1-x²)','1/(1-x²)');
INSERT INTO Translation VALUES('85872d3e-064c-4026-9c45-b0549ff55b72','-1/√(1-x²)','-1/√(1-x²)');
INSERT INTO Translation VALUES('d4f6ed37-8228-4abe-b4dd-ea578e353ddc','The product rule is frequently needed in implicit differentiation.','כלל המכפלה נדרש לעתים קרובות בגזירה מרומזת.');
INSERT INTO Translation VALUES('f31187f1-d969-4f87-b4cc-20afc66d55e7','For x³ + y³ = 3xy, the slope dy/dx at point (3/2, 3/2) equals:','עבור x³ + y³ = 3xy, השיפוע dy/dx בנקודה (3/2, 3/2) שווה ל:');
