INSERT INTO Translation VALUES('39580536-aad7-4d1c-b47f-f0c3190c0fa4','(-ye^(xy) - 1/(x+y)) / (xe^(xy) + 1/(x+y))','(-ye^(xy) - 1/(x+y)) / (xe^(xy) + 1/(x+y))');
INSERT INTO Translation VALUES('5196032e-602d-4658-99fd-6ed9c705bd89','(ye^(xy) + 1/(x+y)) / (xe^(xy) + 1/(x+y))','(ye^(xy) + 1/(x+y)) / (xe^(xy) + 1/(x+y))');
