INSERT INTO Translation VALUES('edf060db-f5e5-470c-8c3b-ed10ea04610c','What is the geometric interpretation of a convex function?','מה הפרשנות הגיאומטרית של פונקציה קמורה?');
INSERT INTO Translation VALUES('6981a27d-9438-4510-9f23-1d1745666362','The graph lies below any chord connecting two points','הגרף נמצא מתחת לכל מיתר המחבר שתי נקודות');
INSERT INTO Translation VALUES('b94f5fd2-de27-4778-81f6-bfa46eb699ff','The graph lies above any chord connecting two points','הגרף נמצא מעל לכל מיתר המחבר שתי נקודות');
INSERT INTO Translation VALUES('61480bbe-0498-4966-af79-5c446a764bd9','The function is always increasing','הפונקציה תמיד עולה');
INSERT INTO Translation VALUES('cbcf0b2f-7fc4-4267-8054-0288a4701fdb','The function has no critical points','לפונקציה אין נקודות קריטיות');
INSERT INTO Translation VALUES('f970514f-0217-400b-b0ba-1753ecfa9cff','A function is convex if its second derivative is non-negative.','פונקציה קמורה אם הנגזרת השנייה שלה אינה שלילית.');
INSERT INTO Translation VALUES('4aeaf98c-666b-4533-99ab-ff53d7995f9d','Which condition must be satisfied for a function to be strictly convex?','איזה תנאי חייב להתקיים כדי שפונקציה תהיה קמורה בקפדנות?');
INSERT INTO Translation VALUES('a174313d-18c7-400e-b35f-6b7c2efa9e5c','f''''(x) > 0 for all x in the domain','f''''(x) > 0 לכל x בתחום');
INSERT INTO Translation VALUES('b5859070-bd8f-45a9-812c-ec33c8d49fd5','f''''(x) ≥ 0 for all x in the domain','f''''(x) ≥ 0 לכל x בתחום');
INSERT INTO Translation VALUES('d715a8ce-8b58-4f17-9d90-38417c7060fc','f''(x) > 0 for all x in the domain','f''(x) > 0 לכל x בתחום');
INSERT INTO Translation VALUES('1777b051-8deb-4f7b-90d5-e6ade5a25525','f(x) > 0 for all x in the domain','f(x) > 0 לכל x בתחום');
INSERT INTO Translation VALUES('15ab282f-d38e-462e-b162-416519aaf12e','What characterizes an inflection point of a function?','מה מאפיין נקודת פיתול של פונקציה?');
INSERT INTO Translation VALUES('dcf27c2b-bee5-40f3-b28b-5e12f60b2f00','The second derivative changes sign','הנגזרת השנייה משנה סימן');
INSERT INTO Translation VALUES('5f2876ae-7a4a-44c5-ad5e-0d9522d69d3d','The first derivative equals zero','הנגזרת הראשונה שווה לאפס');
