INSERT INTO Translation VALUES('bec1b10b-2b5e-4334-95aa-4c47416aa25b','The function is discontinuous','הפונקציה לא רציפה');
INSERT INTO Translation VALUES('0ed1d7d8-3523-4987-9c95-aea4f2e68a8b','At an inflection point, the second derivative must equal zero.','בנקודת פיתול, הנגזרת השנייה חייבת להיות שווה לאפס.');
INSERT INTO Translation VALUES('911a9917-49e9-4cb9-b46e-1ad2c907c307','For the function f(x) = x³, where is the inflection point?','עבור הפונקציה f(x) = x³, איפה נקודת הפיתול?');
INSERT INTO Translation VALUES('15bbd6c1-05ac-426a-8ab1-de4b7fb72b4e','x = 0','x = 0');
INSERT INTO Translation VALUES('ea4be3ac-dd9b-4a83-8955-e61b112385bd','x = 1','x = 1');
INSERT INTO Translation VALUES('1eda34cf-2a71-4213-9ea5-7354a2813b63','x = -1','x = -1');
INSERT INTO Translation VALUES('e4973a93-6fc8-45eb-b146-34430c45dfb4','No inflection point','אין נקודת פיתול');
INSERT INTO Translation VALUES('39b2a60d-e5b6-49e5-82b8-2ddb8f902c97','Which basic differentiation rule applies to d/dx[x^n]?','איזה כלל גזירה בסיסי חל על d/dx[x^n]?');
