INSERT INTO Translation VALUES('fba8b68a-633a-4597-8c5d-122bc3d084a6','Chain Rule','כלל השרשרת');
INSERT INTO Translation VALUES('134ccd7c-7a04-4892-a732-50847084c5d2','The derivative of a constant function is zero.','הנגזרת של פונקציה קבועה היא אפס.');
