INSERT INTO Translation VALUES('2bfaec05-8d77-4f71-ac65-2ec1b8d609da','What is the derivative of a constant multiplied by a function?','מה הנגזרת של קבוע כפול פונקציה?');
INSERT INTO Translation VALUES('85f63886-7349-47a8-9a81-f40b200568a1','The constant times the derivative of the function','הקבוע כפול הנגזרת של הפונקציה');
INSERT INTO Translation VALUES('12f32caf-0261-4068-a80e-be43a7f0bde2','The derivative of the constant times the function','הנגזרת של הקבוע כפול הפונקציה');
