INSERT INTO Translation VALUES('88991eb6-6ac9-4f3e-bca2-6b2e0676158b','The constant plus the derivative of the function','הקבוע ועוד הנגזרת של הפונקציה');
INSERT INTO Translation VALUES('dbf15776-5814-470b-a39d-e3e8c6744231','If f(x) = sin(x²), what is f''(x) using the chain rule?','אם f(x) = sin(x²), מה f''(x) באמצעות כלל השרשרת?');
