INSERT INTO Translation VALUES('c1df5964-3ae4-4834-8173-e247f58f202f','If y = arcsin(x), what is dy/dx?','אם y = arcsin(x), מה dy/dx?');
INSERT INTO Translation VALUES('3c49ad0c-7554-4067-a4ab-627a2e9edbd1','1/√(1-x²)','1/√(1-x²)');
INSERT INTO Translation VALUES('e3eab55d-ae95-4a93-945d-6368014a0cb0','1/(1-x²)','1/(1-x²)');
INSERT INTO Translation VALUES('7e334b3f-9055-4b79-b92f-15e9587c56ba','√(1-x²)','√(1-x²)');
INSERT INTO Translation VALUES('6e43db8c-d2d6-42ef-9d8d-747db2af885b','-1/√(1-x²)','-1/√(1-x²)');
INSERT INTO Translation VALUES('2b05ab41-e01d-43cc-9ef3-cd211180ee58','The derivative of an inverse function can be found using implicit differentiation.','הנגזרת של פונקציה הפוכה ניתן למצוא באמצעות גזירה במשתנה סמוי.');
