INSERT INTO Translation VALUES('943c3663-a8cd-4a53-94fb-60b04923bbd8','What is the derivative of e^x?','מהי הנגזרת של e^x?');
INSERT INTO Translation VALUES('2eb9aa5e-abd2-45ff-9c9e-32e3f51d3b5d','e^x','e^x');
