INSERT INTO Translation VALUES('be53edb3-f2ec-4959-aab1-a3453b68c396','A specific numerical value','ערך מספרי ספציפי');
INSERT INTO Translation VALUES('ce46f293-ae81-44bc-9a6c-829df8cae953','The derivative of a function','הנגזרת של פונקציה');
