INSERT INTO Translation VALUES('a409582b-c47c-4f2a-8ed2-78f8a6aa685b','If F(x) = ∫[a to x] f(t)dt, then F(x) = f(x)','אם F(x) = ∫[a to x] f(t)dt, אז F(x) = f(x)');
