INSERT INTO Translation VALUES('38b6a6ee-a483-487c-b4b4-e24ef2b2af0d','-cos(x)','-cos(x)');
INSERT INTO Translation VALUES('48afd5c0-000c-49c4-9fb3-df3199bfb773','What is the chain rule for differentiation?','מה הוא כלל השרשרת לגזירה?');
INSERT INTO Translation VALUES('4d130cff-229b-4903-b699-4d7401e55208','d/dx[f(g(x))] = f′(g(x)) · g′(x)','d/dx[f(g(x))] = f′(g(x)) · g′(x)');
INSERT INTO Translation VALUES('09626b35-66ed-4d88-9026-0c4527b43749','d/dx[f(g(x))] = f′(x) · g′(x)','d/dx[f(g(x))] = f′(x) · g′(x)');
INSERT INTO Translation VALUES('9c35c0dd-ab86-47f6-837a-c2c3df7676b4','d/dx[f(g(x))] = f(g′(x))','d/dx[f(g(x))] = f(g′(x))');
INSERT INTO Translation VALUES('952b7c39-f86d-4e22-8d14-26b8b3f2ca87','d/dx[f(g(x))] = f′(g(x)) + g′(x)','d/dx[f(g(x))] = f′(g(x)) + g′(x)');
INSERT INTO Translation VALUES('6c6bf0e6-be66-42f8-a892-5ff7294e7fd8','What does the Mean Value Theorem state?','מה קובע משפט ערך הממוצע?');
INSERT INTO Translation VALUES('1a6bdcb1-a9ba-4c19-8f19-4451cf9c5117','If f is continuous on [a,b] and differentiable on (a,b), then ∃c∈(a,b) such that f′(c) = [f(b)-f(a)]/(b-a)','אם f רציפה על [a,b] וגזירה על (a,b), אז קיים c∈(a,b) כך ש-f′(c) = [f(b)-f(a)]/(b-a)');
INSERT INTO Translation VALUES('2be4e890-e822-42ca-a984-47e517e67b94','Every continuous function is differentiable','כל פונקציה רציפה גזירה');
INSERT INTO Translation VALUES('72b172ca-a945-432f-9b4c-847303cdcc4c','The derivative exists at every point','הנגזרת קיימת בכל נקודה');
INSERT INTO Translation VALUES('60d55958-ae5a-4b0f-8ea2-b71016ece9a9','The average value equals the function value somewhere','הערך הממוצע שווה לערך הפונקציה במקום כלשהו');
INSERT INTO Translation VALUES('0722249e-bf9d-40aa-af16-c1792ade5bd1','What is the product rule for differentiation?','מה הוא כלל המכפלה לגזירה?');
INSERT INTO Translation VALUES('b91fe101-b753-4cdb-b728-c828e5b622c7','d/dx[f(x)g(x)] = f′(x)g(x) + f(x)g′(x)','d/dx[f(x)g(x)] = f′(x)g(x) + f(x)g′(x)');
INSERT INTO Translation VALUES('3a071169-1b55-45c1-9a0b-f3d0ae98d85f','d/dx[f(x)g(x)] = f′(x)g′(x)','d/dx[f(x)g(x)] = f′(x)g′(x)');
INSERT INTO Translation VALUES('eba6a775-65fb-4a58-8124-8167da05d97c','d/dx[f(x)g(x)] = f′(x) + g′(x)','d/dx[f(x)g(x)] = f′(x) + g′(x)');
INSERT INTO Translation VALUES('ccedcc94-7f92-4f60-9729-156de72117de','d/dx[f(x)g(x)] = f(x)g′(x)','d/dx[f(x)g(x)] = f(x)g′(x)');
INSERT INTO Translation VALUES('bc5fd51f-40ac-485e-961d-f2ce8f5db1d8','If a function is differentiable at a point, is it necessarily continuous at that point?','אם פונקציה גזירה בנקודה, האם היא בהכרח רציפה באותה נקודה?');
INSERT INTO Translation VALUES('4d6dac3b-a2b9-499f-9153-aa3e29498ec3','Yes, differentiability implies continuity','כן, גזירות גוררת רציפות');
INSERT INTO Translation VALUES('648c63c1-0886-46b2-bbf2-c1349809769e','No, they are independent properties','לא, הם תכונות בלתי תלויות');
INSERT INTO Translation VALUES('638c2b78-b787-4040-9c5d-9f8823efd046','Only for polynomial functions','רק עבור פונקציות פולינומיות');
INSERT INTO Translation VALUES('29b7d742-3160-4ff4-a828-b0227b11ffdd','It depends on the domain','זה תלוי בתחום');
INSERT INTO Translation VALUES('fb522845-f566-4a36-9687-63e5ec583296','What is the antiderivative of 1/x?','מה הנגזרת ההפוכה של 1/x?');
INSERT INTO Translation VALUES('0ed2844d-dcb9-4933-aa56-f0c7deb1f1e4','ln|x| + C','ln|x| + C');
INSERT INTO Translation VALUES('e84c96c5-3d67-44e8-8b66-db3b17fadd31','x² + C','x² + C');
INSERT INTO Translation VALUES('42413aaa-7d61-4348-82ce-b403ad8c5f07','1/x² + C','1/x² + C');
INSERT INTO Translation VALUES('09b7e72a-1caa-4ea4-b725-95719e61f58d','e^x + C','e^x + C');
INSERT INTO Translation VALUES('e578b16a-dabd-4e09-8ff1-1e279b198653','When is a function Riemann integrable on [a,b]?','מתי פונקציה אינטגרבילית לפי רימן על [a,b]?');
INSERT INTO Translation VALUES('14de4cd3-5f28-4edb-a1d0-be1003e8466a','When it is bounded and has at most countably many discontinuities','כאשר היא חסומה ויש לה לכל היותר מספר בן מנייה של אי-רציפויות');
INSERT INTO Translation VALUES('e9e75681-5e20-47ee-a84c-bf695cad6586','When it is continuous everywhere','כאשר היא רציפה בכל מקום');
INSERT INTO Translation VALUES('81f892b4-21a3-4da9-b313-a3b0c143fbaa','When it is differentiable','כאשר היא גזירה');
INSERT INTO Translation VALUES('9421455f-a35c-4a98-aad5-afd54532bd7e','Always','תמיד');
INSERT INTO Translation VALUES('e523b8a2-bcf0-467d-bf7e-ba055e9f9af9','What is Rolle theorem?','מה הוא משפט רול?');
INSERT INTO Translation VALUES('926ef19b-539d-4b46-9aa0-617ec8952d6d','If f is continuous on [a,b], differentiable on (a,b), and f(a) = f(b), then there exists c in (a,b) such that f-prime(c) = 0','אם f רציפה על [a,b], גזירה על (a,b), ו-f(a) = f(b), אז קיים c ב-(a,b) כך ש-f-נגזרת(c) = 0');
INSERT INTO Translation VALUES('03dbc944-f840-44a4-8a02-b87f71fe3488','Every polynomial has at least one real root','לכל פולינום יש לפחות שורש אמיתי אחד');
INSERT INTO Translation VALUES('01d1bc5d-e91f-41d7-8416-d863d14dc885','Continuous functions are differentiable','פונקציות רציפות גזירות');
INSERT INTO Translation VALUES('329e67ef-857b-470d-9877-86ade76731c1','The derivative exists everywhere','הנגזרת קיימת בכל מקום');
INSERT INTO Translation VALUES('c74a1ea6-c2b6-424d-b96d-35fc1e8180b3','If f-prime(x) > 0 for all x in an interval, then f is:','אם הנגזרת של f גדולה מ-0 לכל x במרווח, אז f היא:');
INSERT INTO Translation VALUES('397e532a-7fa7-4dc4-8591-fad240305450','Strictly increasing on that interval','עולה בקפדנות במרווח זה');
INSERT INTO Translation VALUES('60158a85-461c-49b8-bacc-f41c82d5413d','Strictly decreasing on that interval','יורדת בקפדנות במרווח זה');
INSERT INTO Translation VALUES('07ffd8fb-56ed-4b8a-96ff-9ed6b4bd3f6b','Constant on that interval','קבועה במרווח זה');
INSERT INTO Translation VALUES('fc1b66b4-ac44-4e67-a9ab-802ddfd1f9d2','Has a maximum at every point','יש לה מקסימום בכל נקודה');
INSERT INTO Translation VALUES('73b97da4-a41d-4523-9bbe-1df2a44aa390','What is the basic idea behind integration by substitution?','מה הרעיון הבסיסי מאחורי אינטגרציה בשיטת ההצבה?');
INSERT INTO Translation VALUES('f4a5b439-7418-4a75-afd8-e0dfbb61a2b5','Transform the integral into a simpler form using change of variables','להפוך את האינטגרל לצורה פשוטה יותר באמצעות שינוי משתנים');
INSERT INTO Translation VALUES('035b4442-4774-4800-8724-434c16c372d1','Replace all variables with constants','להחליף את כל המשתנים בקבועים');
INSERT INTO Translation VALUES('37cd6f36-a532-4d71-b155-bc91c54e38b3','Split the integral into parts','לפצל את האינטגרל לחלקים');
INSERT INTO Translation VALUES('f4817041-3829-4652-a8eb-b4290f0f6cf2','Use numerical approximation','להשתמש בקירוב מספרי');
INSERT INTO Translation VALUES('6a62ed23-7878-4e2c-b4e9-2279bc7e0e0a','What is the fundamental theorem of calculus (first part)?','מה המשפט היסודי של החשבון (חלק ראשון)?');
INSERT INTO Translation VALUES('763a2202-a940-47b3-ba89-fadabf395c14','If f is continuous on [a,b], then F(x) = integral from a to x of f(t)dt is differentiable and F-prime(x) = f(x)','אם f רציפה על [a,b], אז F(x) = אינטגרל מ-a עד x של f(t)dt גזירה ו-F-נגזרת(x) = f(x)');
INSERT INTO Translation VALUES('85ee8cda-7545-4d98-8c72-457ca66a2e7a','Integration and differentiation are inverse operations','אינטגרציה וגזירה הן פעולות הפוכות');
INSERT INTO Translation VALUES('ede05071-161c-4f3f-aa0c-b1234be70020','Every function has an antiderivative','לכל פונקציה יש נגזרת הפוכה');
INSERT INTO Translation VALUES('0d15ae7e-765a-4852-a628-d39773ef1684','The area under a curve equals the function value','השטח מתחת לעקומה שווה לערך הפונקציה');
INSERT INTO Translation VALUES('710d58f8-9503-4a20-85fa-91cf632c7d96','What does the mean value theorem for integrals state?','מה קובע משפט ערך הממוצע לאינטגרלים?');
INSERT INTO Translation VALUES('52b59102-32bf-4cd9-ad14-d9a28c2fc3ad','If f is continuous on [a,b], then there exists c in [a,b] such that integral of f from a to b equals f(c)*(b-a)','אם f רציפה על [a,b], אז קיים c ב-[a,b] כך שהאינטגרל של f מ-a עד b שווה ל-f(c)*(b-a)');
INSERT INTO Translation VALUES('d1a19115-628e-4bc3-893f-1cfeab3707db','The integral equals the average value','האינטגרל שווה לערך הממוצע');
INSERT INTO Translation VALUES('103eae2e-8f59-4006-b373-6ecb71f2461f','Every integral has a mean','לכל אינטגרל יש ממוצע');
INSERT INTO Translation VALUES('b6f276b4-f812-4764-869f-ca6aad13a2fc','Integration preserves averages','אינטגרציה משמרת ממוצעים');
INSERT INTO Translation VALUES('e4133280-e25c-43bb-983b-e8cc05a7516b','What is the second fundamental theorem of calculus?','מה המשפט היסודי השני של החשבון?');
INSERT INTO Translation VALUES('7b94c0b9-2d5e-4951-881f-e5ae6e8b8842','If F is an antiderivative of f, then integral of f from a to b equals F(b) - F(a)','אם F היא נגזרת הפוכה של f, אז אינטגרל של f מ-a עד b שווה ל-F(b) - F(a)');
INSERT INTO Translation VALUES('135ebbab-8587-4960-95f9-a454e9dc4816','Derivatives and integrals commute','נגזרות ואינטגרלים מתחלפים');
INSERT INTO Translation VALUES('f09deacf-943f-43e1-adde-66825221dd86','Every continuous function is integrable','כל פונקציה רציפה אינטגרבילית');
INSERT INTO Translation VALUES('a935724a-6545-46de-85b0-20f958bffd2a','Integration by parts always works','אינטגרציה בחלקים תמיד עובדת');
INSERT INTO Translation VALUES('2bd591f0-57bd-467e-a002-923dcaecd969','When does an improper integral of the first kind converge?','מתי אינטגרל לא תקין מהסוג הראשון מתכנס?');
INSERT INTO Translation VALUES('d47659a7-1a06-41b4-8af7-e0a3b33981d0','When the limit as the upper bound approaches infinity exists and is finite','כאשר הגבול כשהגבול העליון מתקרב לאינסוף קיים וסופי');
INSERT INTO Translation VALUES('368fd2cf-66fa-4ba3-9d67-3ad5aad791cd','When the integrand is continuous','כאשר הפונקציה המאונטגרלת רציפה');
INSERT INTO Translation VALUES('0fb4e2ef-7f3d-42d2-8d2d-2de44983d00e','Always','תמיד');
INSERT INTO Translation VALUES('5f3f4a1e-6bf6-4e4b-8afe-57f50f5f52e4','Never','אף פעם');
INSERT INTO Translation VALUES('76e97629-2d75-45cc-805f-71b239d043be','What characterizes a convergent sequence?','מה מאפיין סדרה מתכנסת?');
INSERT INTO Translation VALUES('ec692b8b-368e-4615-94d3-338b22a99b49','The terms approach a finite limit as n approaches infinity','האיברים מתקרבים לגבול סופי כש-n מתקרב לאינסוף');
INSERT INTO Translation VALUES('bf4e12e5-5a85-4d21-b666-2176d61291d0','The terms are always increasing','האיברים תמיד עולים');
INSERT INTO Translation VALUES('28615a40-d000-4cbb-beeb-2aba27334e28','The terms are bounded','האיברים חסומים');
INSERT INTO Translation VALUES('e7e507b9-9fae-405e-88fb-e0b1407c3632','The sequence is finite','הסדרה סופית');
INSERT INTO Translation VALUES('73e2a573-e47f-4926-957c-8853f47bccba','What is the epsilon-delta definition of sequence limit?','מה ההגדרה אפסילון-דלתא של גבול סדרה?');
INSERT INTO Translation VALUES('3f555e67-a586-442c-a38a-0e28b16b8093','For every epsilon > 0, there exists N such that for all n > N, |a_n - L| < epsilon','לכל אפסילון > 0, קיים N כך שלכל n > N, |a_n - L| < אפסילון');
INSERT INTO Translation VALUES('8d0daa7d-4246-46a6-bc30-40d0721358e9','The sequence is within epsilon of L for large n','הסדרה נמצאת במרחק אפסילון מ-L עבור n גדול');
INSERT INTO Translation VALUES('0cb24bba-81cd-4501-90e6-4085b626b269','The distance between consecutive terms is small','המרחק בין איברים עוקבים קטן');
INSERT INTO Translation VALUES('794ea493-98cf-4360-a14a-221b4e15efab','The sequence converges uniformly','הסדרה מתכנסת באופן אחיד');
INSERT INTO Translation VALUES('85854d25-73ce-4c1e-a4e2-531d7db8ec8c','How do you prove a limit does not exist?','איך מוכיחים שגבול לא קיים?');
INSERT INTO Translation VALUES('00408a32-f2c4-4397-ad26-384ede8525cc','Show that different subsequences converge to different limits','להראות שתת-סדרות שונות מתכנסות לגבולות שונים');
INSERT INTO Translation VALUES('6e85205a-01cb-4496-8aeb-103c7a815687','Show the sequence is unbounded','להראות שהסדרה לא חסומה');
INSERT INTO Translation VALUES('00cfed67-2ddb-46dc-b266-4a713a70391a','Show the sequence oscillates','להראות שהסדרה מתנדנדת');
INSERT INTO Translation VALUES('6f077e06-d423-48c1-998d-2a540371fd5c','Use the ratio test','להשתמש במבחן היחס');
INSERT INTO Translation VALUES('4c1ffaf7-4094-4d29-8560-e04ba1f13946','What is the limit of (1 + 1/n)^n as n approaches infinity?','מה הגבול של (1 + 1/n)^n כש-n מתקרב לאינסוף?');
INSERT INTO Translation VALUES('712a8630-258b-45a9-b37e-61c7f34b95fd','e (Euler number)','e (מספר אוילר)');
INSERT INTO Translation VALUES('4b9d676a-6112-424f-b210-abf7447aa57a','1','1');
INSERT INTO Translation VALUES('b521b3d3-a714-4393-b708-9817c7b08e82','infinity','אינסוף');
INSERT INTO Translation VALUES('1ec0fece-78b3-4cee-a89e-aea0adbaa701','0','0');
INSERT INTO Translation VALUES('cf23b6cd-b949-49f3-933d-ecd598f48043','What does it mean for a sequence to diverge to infinity?','מה פירוש שסדרה מתבדרת לאינסוף?');
INSERT INTO Translation VALUES('250db24d-28e0-4062-b200-5716174df4ea','For every M > 0, there exists N such that for all n > N, a_n > M','לכל M > 0, קיים N כך שלכל n > N, a_n > M');
INSERT INTO Translation VALUES('c2b08b70-5db9-4e92-8fb9-e65730467308','The sequence approaches infinity slowly','הסדרה מתקרבת לאינסוף לאט');
INSERT INTO Translation VALUES('61f6c07b-74b2-4db8-a1d7-ab9c909517f7','The sequence has no upper bound','לסדרה אין חסם עליון');
INSERT INTO Translation VALUES('ee259f07-44d1-4b79-b248-4364426e3342','The terms grow exponentially','האיברים גדלים באופן אקספוננציאלי');
INSERT INTO Translation VALUES('b556f0b0-d030-459b-ac63-5f2db83c04ad','What is a bounded sequence?','מה היא סדרה חסומה?');
INSERT INTO Translation VALUES('77411db3-7ee4-4a10-a28b-f9c6b3eee07f','A sequence where there exist real numbers m and M such that m ≤ a_n ≤ M for all n','סדרה שעבורה קיימים מספרים ממשיים m ו-M כך ש-m ≤ a_n ≤ M לכל n');
INSERT INTO Translation VALUES('1b0d8d9e-79e8-4817-a9ed-692510284139','A sequence that converges','סדרה המתכנסת');
INSERT INTO Translation VALUES('be0c0228-fa23-416e-9191-ee7a9097d5c1','A finite sequence','סדרה סופית');
INSERT INTO Translation VALUES('5dbc1137-b6fc-4ea0-a1f7-3a727aeaf2b2','A monotonic sequence','סדרה מונוטונית');
INSERT INTO Translation VALUES('4c5e090b-8d6e-4423-814b-074a57d3cde9','If a_n ≤ b_n ≤ c_n for all n and lim a_n = lim c_n = L, what can we conclude about lim b_n?','אם a_n ≤ b_n ≤ c_n לכל n ו-lim a_n = lim c_n = L, מה ניתן להסיק על lim b_n?');
INSERT INTO Translation VALUES('4e034926-5961-4ae7-8e3a-610a7159cb2e','lim b_n = L (by the squeeze theorem)','lim b_n = L (לפי משפט הסנדוויץ)');
INSERT INTO Translation VALUES('3fa781c7-9ca3-4d02-8bcb-ede9181e108a','lim b_n does not exist','lim b_n לא קיים');
INSERT INTO Translation VALUES('f8d8ad5f-9602-4c87-bfb9-3840a499e572','We cannot determine lim b_n','לא ניתן לקבוע את lim b_n');
INSERT INTO Translation VALUES('bdacd2b6-84e6-49a7-a0ae-72d7b4d59ec5','lim b_n = 0','lim b_n = 0');
INSERT INTO Translation VALUES('dbcd449a-ddc9-414c-8653-ea76f6d3fc8d','What is the squeeze theorem for infinite limits?','מה משפט הסנדוויץ לגבולות אינסופיים?');
INSERT INTO Translation VALUES('e42e60a2-6f8a-41e4-ad48-1af5638d2016','If a_n ≤ b_n and lim a_n = infinity, then lim b_n = infinity','אם a_n ≤ b_n ו-lim a_n = אינסוף, אז lim b_n = אינסוף');
INSERT INTO Translation VALUES('47e83095-c815-4c59-9408-9e960278e6bc','Infinite limits cannot be squeezed','גבולות אינסופיים לא ניתנים לסחיטה');
INSERT INTO Translation VALUES('3a9e580e-a09e-48c3-b8ae-4df4ee961e28','Only works for finite limits','עובד רק עבור גבולות סופיים');
INSERT INTO Translation VALUES('8600ccb4-2c8b-4ec4-966c-4862a836fbf0','Requires three sequences','דורש שלוש סדרות');
INSERT INTO Translation VALUES('75bb5393-8f47-408c-bf76-f80a9066fa28','In the comparison test for series, if 0 ≤ a_n ≤ b_n and sum b_n converges, what can we conclude?','במבחן ההשוואה לטורים, אם 0 ≤ a_n ≤ b_n וסכום b_n מתכנס, מה ניתן להסיק?');
INSERT INTO Translation VALUES('e96f7edb-5f09-4c49-b090-681edbf0ccb6','sum a_n also converges','סכום a_n גם מתכנס');
INSERT INTO Translation VALUES('aa645f2b-07b4-4155-8e28-592f133e2165','sum a_n diverges','סכום a_n מתבדר');
INSERT INTO Translation VALUES('2bf5f3c0-76e0-49c5-bea2-c789cbf6f96e','We cannot conclude anything','לא ניתן להסיק דבר');
INSERT INTO Translation VALUES('fc123f47-6c38-463f-9048-982d6660cef4','sum a_n converges conditionally','סכום a_n מתכנס בתנאי');
INSERT INTO Translation VALUES('1205f1a6-e1cb-4579-a517-c110ad631834','What is the limit comparison test?','מה הוא מבחן השוואת הגבולות?');
INSERT INTO Translation VALUES('286acc14-ced9-49cd-8ea2-b3ea2bb68441','If lim(a_n/b_n) = c > 0 and finite, then sum a_n and sum b_n have the same convergence behavior','אם lim(a_n/b_n) = c > 0 וסופי, אז לסכום a_n וסכום b_n יש אותה התנהגות התכנסות');
INSERT INTO Translation VALUES('929df051-33df-4c73-8d6c-fab7e8149c74','Compare the limits of the terms directly','להשוות את הגבולות של האיברים ישירות');
