INSERT INTO Translation VALUES('cd27cb87-beca-45f7-aff1-ea60fca3a199','Endpoint evaluation is necessary when finding absolute extrema on closed intervals.','הערכת נקודות קצה הכרחית כאשר מוצאים קיצונים מוחלטים בקטעים סגורים.');
