INSERT INTO Translation VALUES('b470f920-0f39-4d73-83f4-55a0821066d2','It never holds','הוא אף פעם לא מתקיים');
INSERT INTO Translation VALUES('2f4b99f6-4dde-4b96-b625-95e1fc458190','It becomes a tautology','הוא הופך לטאוטולוגיה');
INSERT INTO Translation VALUES('7a9b9274-6151-4541-aff9-64fa661afe48','What is the cardinality of the power set of a set with n elements?','מה העוצמה של קבוצת החזקה של קבוצה עם n איברים?');
INSERT INTO Translation VALUES('da8d3a8a-919a-433c-9a5e-e133d72ebc0c','2^n','2^n');
