INSERT INTO Translation VALUES('3abd0fa5-2d52-42d8-aae3-9cc1e355fe40','Meter','מטר');
INSERT INTO Translation VALUES('ec53ad39-cb45-4740-82df-38f804c27aae','Second','שנייה');
INSERT INTO Translation VALUES('5a3da2fc-7cdb-4e7a-a0ad-ff05bcc4f8b5','Kelvin','קלווין');
INSERT INTO Translation VALUES('a388606c-250d-4dfa-b59c-7e4545b4a995','The SI base unit for temperature is Kelvin.','יחידת הבסיס SI לטמפרטורה היא קלווין.');
INSERT INTO Translation VALUES('748967c1-03c9-4e11-a772-0455aa5561fa','Which of the following is a tautology?','איזה מהבאים הוא טאוטולוגיה?');
INSERT INTO Translation VALUES('3277f364-249a-485b-b032-cb824b80c670','P ∨ ¬P','P ∨ ¬P');
INSERT INTO Translation VALUES('cd083cd8-89f9-4b75-b69e-8c9b6310c868','P ∧ ¬P','P ∧ ¬P');
INSERT INTO Translation VALUES('472c6c8e-195e-44b2-9084-a2be396e6c1a','P → Q','P → Q');
INSERT INTO Translation VALUES('02e36091-6611-452f-9a69-4ed104202e4d','P ∧ Q','P ∧ Q');
INSERT INTO Translation VALUES('462bcf05-5fe3-40d5-9457-f02291871982','The statement ∀x∃y P(x,y) means that for every x, there exists a y such that P(x,y) is true.','המשפט ∀x∃y P(x,y) פירושו שלכל x, קיים y כזה ש-P(x,y) הוא אמת.');
INSERT INTO Translation VALUES('77472ec6-6342-4983-9284-a7f3d0b0efd1','Which step is typically first in the formalization process?','איזה שלב הוא בדרך כלל הראשון בתהליך הפורמליזציה?');
INSERT INTO Translation VALUES('411e7d62-2555-43d5-bb04-da0dd849f61a','Identifying the domain of discourse','זיהוי תחום השיח');
INSERT INTO Translation VALUES('fe790b42-c9da-4ef5-b00a-230176b62095','Choosing logical connectives','בחירת קשרים לוגיים');
INSERT INTO Translation VALUES('80e2e6c1-03a0-4e57-8681-d900d0ae7a57','Writing the proof','כתיבת ההוכחה');
INSERT INTO Translation VALUES('2f4aa5b2-1b48-44c7-a9bc-04c0c05aacda','Evaluating truth values','הערכת ערכי אמת');
INSERT INTO Translation VALUES('5fea3e55-06b9-4da2-b46e-7342152b2af9','Structural induction can be applied to prove properties of formal languages.','אינדוקציה מבנית יכולה להיות מיושמת להוכחת תכונות של שפות פורמליות.');
INSERT INTO Translation VALUES('9b22ad97-8220-41d4-9c74-05161f184def','What does it mean for a formula to be satisfiable?','מה המשמעות של כך שנוסחה ספיקה?');
INSERT INTO Translation VALUES('10c08bae-0eae-4834-a843-ab29ca727b7b','There exists at least one model where it is true','קיים לפחות מודל אחד שבו היא אמת');
INSERT INTO Translation VALUES('5dd590dc-d62c-41d6-a9db-f48b2d1b65b7','It is true in all models','היא אמת בכל המודלים');
INSERT INTO Translation VALUES('c9b63ac6-4fc3-444b-9306-8227c11c37a7','It can be syntactically derived','היא יכולה להיות נגזרת תחבירית');
INSERT INTO Translation VALUES('c856ae40-7079-4b53-93cd-ec0409d0d9ca','It contains no logical connectives','היא לא מכילה קשרים לוגיים');
INSERT INTO Translation VALUES('d93dfcdd-af66-4911-aba3-d9f5605859a3','What is the relationship between satisfiability and consistency?','מה הקשר בין ספיקות ועקביות?');
INSERT INTO Translation VALUES('f3e24762-9ed9-4375-8d44-c617b7fb5aa1','A set is satisfiable if and only if it is consistent','קבוצה ספיקה אם ורק אם היא עקבית');
INSERT INTO Translation VALUES('5809dbb4-0ef0-48b3-9b8e-bd4b925e6d2e','Satisfiability implies consistency but not vice versa','ספיקות גוררת עקביות אך לא להיפך');
INSERT INTO Translation VALUES('d157e955-fc9e-49ea-b8e8-68a716173651','Consistency implies satisfiability but not vice versa','עקביות גוררת ספיקות אך לא להיפך');
