INSERT INTO Translation VALUES('afc2c942-0d1a-4501-a6e9-ee912108eaac','Disjunctive Syllogism','סילוגיזם דיסיונקטיבי');
INSERT INTO Translation VALUES('2b69b483-0f10-4418-9825-febbbc71b68c','What is the basic derivative of x^n?','מהי הנגזרת הבסיסית של x^n?');
