INSERT INTO Translation VALUES('036ecb80-7988-4d9b-8dea-e9aee47b7778','R can be either true or false','R יכול להיות נכון או שקרי');
INSERT INTO Translation VALUES('f2a2727f-02ba-442d-bff3-b9fadc66d527','Cannot determine R without additional information','לא ניתן לקבוע את R ללא מידע נוסף');
INSERT INTO Translation VALUES('10cc78fd-3af3-437c-a38d-84e316f8bb9f','If a set of propositions {P, ¬P, Q} is given, what can we say about its consistency?','אם נתונה קבוצת הפסוקים {P, ¬P, Q}, מה ניתן לומר על עקביותה?');
