INSERT INTO Translation VALUES('a9cbe352-0fc5-49b8-8017-8b80c5ebb2bc','Its consistency depends on the logical system being used','עקביותו תלויה במערכת הלוגית שבה נעשה שימוש');
INSERT INTO Translation VALUES('816f5ffa-83dd-4848-81a3-d722b5ee7952','What does it mean for a function f(x) = g(x)^(-1) to be the inverse of g(x)?','מה המשמעות של כך שפונקציה f(x) = g(x)^(-1) היא הפונקציה ההפוכה של g(x)?');
