INSERT INTO Translation VALUES('7a7c6ad4-0b39-4ee6-9357-d17fca0a614a','2n','2n');
INSERT INTO Translation VALUES('05d43852-232e-4511-97ed-41758ad836e7','Which operation represents the set difference A \ B?','איזה פעולה מייצגת את הפרש הקבוצות A \ B?');
INSERT INTO Translation VALUES('6dc15105-4b37-4bc7-8ff7-8f911efae3e9','Elements in A but not in B','איברים ב-A אבל לא ב-B');
INSERT INTO Translation VALUES('e7a003ba-5210-4299-8d9f-8a5d37f04408','Elements in both A and B','איברים גם ב-A וגם ב-B');
INSERT INTO Translation VALUES('a775adc5-0132-4866-bc05-787cfea398f7','Elements in A or B','איברים ב-A או ב-B');
INSERT INTO Translation VALUES('17969046-3386-4d2e-917f-4f81bb477ccb','Elements in neither A nor B','איברים שלא ב-A ולא ב-B');
INSERT INTO Translation VALUES('f631fb17-15b3-4c56-884b-cffdb52308aa','The Axiom of Choice is equivalent to Zorn''s lemma.','אקסיומת הבחירה שקולה ללמה של צורן.');
INSERT INTO Translation VALUES('624cd552-50d7-4c9c-88e8-052eb62cf0c8','What is Russell''s paradox?','מהי הפרדוקס של ראסל?');
INSERT INTO Translation VALUES('a23f1757-a8e6-42e1-91ff-469d6cf10631','The set of all sets that do not contain themselves','קבוצת כל הקבוצות שלא מכילות את עצמן');
INSERT INTO Translation VALUES('050eb00e-485f-439f-9a83-0cb580d77e9c','The set of all infinite sets','קבוצת כל הקבוצות האינסופיות');
INSERT INTO Translation VALUES('980766a1-ac28-44bc-8b27-843e3a026d94','The set of all prime numbers','קבוצת כל המספרים הראשוניים');
