INSERT INTO Translation VALUES('25f05695-d96c-436f-82d6-2e3a9848da9a','Truth values in classical logic are binary (true or false).','ערכי אמת בלוגיקה קלאסית הם בינאריים (אמת או שקר).');
INSERT INTO Translation VALUES('86d8c417-dc2a-4383-b0e8-f1b0134f0328','What is the truth value of (True ∧ False)?','מה ערך האמת של (True ∧ False)?');
