INSERT INTO Translation VALUES('3eaf6299-9d1f-4b6d-8655-34e3506522e0','Undefined','לא מוגדר');
INSERT INTO Translation VALUES('9559a1d6-0f07-42fd-a8b6-e232effcf3ac','In three-valued logic, what is the third truth value typically called?','בלוגיקה תלת-ערכית, איך נקרא בדרך כלל ערך האמת השלישי?');
