INSERT INTO Translation VALUES('fddedce9-c08c-43b1-a3c6-15993bbbe8a5','Contradictory','סותר');
INSERT INTO Translation VALUES('bec1d8d5-418a-4b48-8850-a51bed715d9f','In fuzzy logic, truth values can be any real number between 0 and 1.','בלוגיקה מטושטשת, ערכי אמת יכולים להיות כל מספר ממשי בין 0 ל-1.');
INSERT INTO Translation VALUES('1bdd8c28-aab4-45a3-9bba-c57fcd03d2c8','What happens to the law of excluded middle in three-valued logic?','מה קורה לחוק השלישי הנמנע בלוגיקה תלת-ערכית?');
INSERT INTO Translation VALUES('c0ef2a31-7ca6-4439-9c66-af27da8a1c46','It may not hold for all propositions','הוא עלול לא להתקיים לכל ההצעות');
