INSERT INTO Translation VALUES('9a9c3e1e-bed6-4632-8c87-a741e8b85306','It never holds','הוא אף פעם לא מתקיים');
INSERT INTO Translation VALUES('13b44c74-28e3-4903-8209-13fd628431ca','It becomes a tautology','הוא הופך לטאוטולוגיה');
INSERT INTO Translation VALUES('243d3ae1-5e39-43a6-8cb9-4616f16b62e0','In which context are non-classical truth values most commonly used?','באיזה הקשר נעשה השימוש הנפוץ ביותר בערכי אמת לא קלאסיים?');
