INSERT INTO Translation VALUES('bdd307f8-09bc-4704-a25e-648b611b43da','In graph theory, what is a vertex?','בתורת הגרפים, מהו קודקוד?');
INSERT INTO Translation VALUES('c598c6f7-f6fe-4e8a-af4b-77c551f55a35','A point or node in the graph','נקודה או צומת בגרף');
INSERT INTO Translation VALUES('831a4af1-9dbe-46a4-9fdf-6a64ad92c1a2','A connection between two points','קשר בין שתי נקודות');
INSERT INTO Translation VALUES('5dd48196-2efd-42e7-86b5-2fc1a6675b94','The weight of an edge','המשקל של קשת');
INSERT INTO Translation VALUES('a3513417-922d-4b00-9f0b-9d796eb90a9e','The direction of movement','כיוון התנועה');
INSERT INTO Translation VALUES('7fd13136-2c21-47ba-95f4-5d9aa2e908de','An edge connects two vertices in a graph.','קשת מחברת שני קודקודים בגרף.');
INSERT INTO Translation VALUES('98a64000-ad8d-410d-a95b-a28a5138d07a','What is the degree of a vertex in an undirected graph?','מהי הדרגה של קודקוד בגרף לא מכוון?');
INSERT INTO Translation VALUES('fb07f8ac-8e27-4362-a879-7f5996cc89ef','The number of edges connected to it','מספר הקשתות המחוברות אליו');
INSERT INTO Translation VALUES('b7128aaa-a100-4824-9961-15f33b458c82','The number of vertices it can reach','מספר הקודקודים שהוא יכול להגיע אליהם');
