INSERT INTO Translation VALUES('45b9b478-52ea-4ad5-afd8-4235e33e91c1','The shortest path to it','הדרך הקצרה ביותר אליו');
INSERT INTO Translation VALUES('c7d8600d-c4ff-4e42-a2be-ef4e9e6dfcfd','A tree is a connected graph with:','עץ הוא גרף קשיר עם:');
INSERT INTO Translation VALUES('6e6a9017-727a-4339-9b6d-8b93e6940566','No cycles','ללא מעגלים');
INSERT INTO Translation VALUES('31355b6c-54aa-4fc9-b424-c934e54da191','Exactly one cycle','בדיוק מעגל אחד');
INSERT INTO Translation VALUES('e9d05e54-fd8c-46a0-9a27-90ba59aabb87','Multiple cycles','מעגלים מרובים');
