INSERT INTO Translation VALUES('4be2559c-d302-4fbe-8a30-5c7c1c63d8e0','A complete graph with n vertices has n(n-1)/2 edges.','גרף שלם עם n קודקודים יש לו n(n-1)/2 קשתות.');
INSERT INTO Translation VALUES('ebc58cb6-f222-4e0d-9da9-ce0686afe9cd','What is the chromatic number of a graph?','מהו המספר הכרומטי של גרף?');
INSERT INTO Translation VALUES('37f24953-a02d-4398-8cd6-27233009ed8f','The minimum number of colors needed to color vertices','המספר המינימלי של צבעים הדרושים לצביעת קודקודים');
INSERT INTO Translation VALUES('6987f490-b78d-409b-81c5-20063cfed824','The number of vertices in the graph','מספר הקודקודים בגרף');
