INSERT INTO Translation VALUES('2561df78-3784-4d3d-831c-b31b4101077d','The length of the longest path','אורך הדרך הארוכה ביותר');
INSERT INTO Translation VALUES('b82abbf5-16ea-4b96-baef-35ed9a3e6367','What does n! (n factorial) represent?','מה מייצג n! (n עצרת)?');
INSERT INTO Translation VALUES('177e9167-6851-4554-9be2-8d1693360e4b','The product of all positive integers from 1 to n','המכפלה של כל המספרים השלמים החיוביים מ-1 עד n');
