INSERT INTO Translation VALUES('20837314-83b8-4f76-9968-9a2c7e27497b','C(n,r) or ''n choose r''','C(n,r) או ''n בוחר r''');
INSERT INTO Translation VALUES('aeb60f70-e7a6-4fd1-ba40-7092a88bdcd7','P(n,r)','P(n,r)');
