INSERT INTO Translation VALUES('f56aee70-ad21-402d-af8c-f65a424cba01','n! / (r!(n-r)!)','n! / (r!(n-r)!)');
INSERT INTO Translation VALUES('fac5a737-1ce9-49c7-b2a4-9e6749b59446','n! / r!','n! / r!');
INSERT INTO Translation VALUES('9f126704-6c2a-4dba-8caf-7ab2d2c2bc5b','n^r','n^r');
INSERT INTO Translation VALUES('f1d92e26-f7f2-4459-8cf2-9d0dea8d15f2','n + r','n + r');
INSERT INTO Translation VALUES('8ee54308-582d-4736-87dc-0fdd653a33ee','The pigeonhole principle states that if n pigeons are placed in m pigeonholes with n > m, then at least one pigeonhole contains more than one pigeon.','עקרון שובך היונים קובע שאם n יונים ממוקמות ב-m שובכים עם n > m, אז לפחות שובך אחד מכיל יותר מיונה אחת.');
INSERT INTO Translation VALUES('22e404ce-6f06-4b3a-ae20-2916346ba7d9','What is the generating function for the sequence 1, 1, 1, 1, ...?','מהי הפונקציה היוצרת לסדרה 1, 1, 1, 1, ...?');
INSERT INTO Translation VALUES('3441f799-09d9-45c9-b27d-446608299e8b','1/(1-x)','1/(1-x)');
INSERT INTO Translation VALUES('8e398181-9001-40b5-bb08-b1eae0964396','1 + x + x² + x³','1 + x + x² + x³');
