INSERT INTO Translation VALUES('c9360319-1f72-4e4c-9038-ea5bcf88c6f9','1 + x','1 + x');
INSERT INTO Translation VALUES('454eaf49-d22d-4991-8444-903db7cc50a7','A vector space must satisfy which of the following properties?','מרחב וקטורי חייב לקיים איזה מהתכונות הבאות?');
INSERT INTO Translation VALUES('8a27c863-2a7b-47d2-ae9a-129b5610ff27','Closure under addition and scalar multiplication','סגירות תחת חיבור וכפל בסקלר');
INSERT INTO Translation VALUES('b7665655-0162-4fc1-9c5e-66c4df2897df','Only closure under addition','רק סגירות תחת חיבור');
INSERT INTO Translation VALUES('585cd532-82e3-47d0-aa03-ae7bfe7739a7','Only closure under multiplication','רק סגירות תחת כפל');
INSERT INTO Translation VALUES('102690eb-e6df-4cab-bb0b-5876664137ba','Finite dimension only','מימד סופי בלבד');
INSERT INTO Translation VALUES('5e2a40cd-f5d9-46d4-b44a-75bd1b297015','The zero vector is unique in any vector space.','וקטור האפס הוא יחיד בכל מרחב וקטורי.');
INSERT INTO Translation VALUES('e90f7cb4-40dd-4e40-86e9-96db870c922b','What is a basis of a vector space?','מהו בסיס של מרחב וקטורי?');
INSERT INTO Translation VALUES('4dd87fd1-7baf-4274-9c2c-5dd7671238b7','A linearly independent set that spans the space','קבוצה בלתי תלויה ליניארית שפורשת את המרחב');
INSERT INTO Translation VALUES('7f523ade-1d44-4e72-bc8b-2751ccb270b1','Any set of vectors in the space','כל קבוצת וקטורים במרחב');
INSERT INTO Translation VALUES('34142570-3661-431d-b630-6eb1de1d9ceb','The largest set of vectors','הקבוצה הגדולה ביותר של וקטורים');
INSERT INTO Translation VALUES('3b77cf14-0afc-4fce-8ff8-df67b7468738','Only orthogonal vectors','רק וקטורים אורתוגונליים');
INSERT INTO Translation VALUES('97e7b898-48a9-4c1a-a301-40ea7b34784e','The dimension of a vector space is:','המימד של מרחב וקטורי הוא:');
INSERT INTO Translation VALUES('8291ec67-cb16-447c-9f44-c33b390f12ce','The number of vectors in any basis','מספר הוקטורים בכל בסיס');
INSERT INTO Translation VALUES('0d35ba95-d288-4a27-8e75-f8129e63623d','The total number of vectors in the space','המספר הכולל של וקטורים במרחב');
INSERT INTO Translation VALUES('167475c3-7a3d-4339-8ac9-e5a17c18fc62','Always infinite','תמיד אינסופי');
INSERT INTO Translation VALUES('df7c4906-5ae3-45b0-8e42-d5c579229b79','The length of the longest vector','האורך של הוקטור הארוך ביותר');
INSERT INTO Translation VALUES('e604d269-62c4-477a-ada4-cc2db31f2641','Any two bases of the same vector space have the same number of elements.','לכל שני בסיסים של אותו מרחב וקטורי יש אותו מספר איברים.');
INSERT INTO Translation VALUES('828976c6-78b0-4dd3-ac99-d0a3b99d9cc0','What does the continuation of monotonicity theorem state about increasing functions?','מה קובע משפט המשך המונוטוניות על פונקציות עולות?');
INSERT INTO Translation VALUES('c8f44552-c56d-4edb-8aa2-e1af042308cd','An increasing function remains increasing when extended','פונקציה עולה נשארת עולה כשמרחיבים אותה');
INSERT INTO Translation VALUES('49501dea-1998-4eea-883c-2a0638ae4d79','An increasing function becomes decreasing when extended','פונקציה עולה הופכת יורדת כשמרחיבים אותה');
INSERT INTO Translation VALUES('144f9ecf-a758-4502-86a0-a50953d24b6b','Monotonicity cannot be continued','לא ניתן להמשיך מונוטוניות');
INSERT INTO Translation VALUES('92410e58-d802-4c84-8947-a8e5dec219bd','Extension always changes monotonicity','הרחבה תמיד משנה מונוטוניות');
INSERT INTO Translation VALUES('cb60551d-5609-4a66-935f-900b9c124015','If f is strictly increasing on [a,b], then any extension must also be strictly increasing.','אם f עולה ממש על [a,b], אז כל הרחבה חייבת להיות עולה ממש.');
INSERT INTO Translation VALUES('3b014035-666d-40b6-9cb5-719e563c55d8','What is the main property of a monotonic function?','מה התכונה העיקרית של פונקציה מונוטונית?');
INSERT INTO Translation VALUES('f4321181-ff48-46c4-9ac2-db0170f87e7c','It preserves order relations','היא שומרת על יחסי סדר');
INSERT INTO Translation VALUES('27b344d0-b141-4976-be64-140c7c4a52db','It is always continuous','היא תמיד רציפה');
INSERT INTO Translation VALUES('957085f0-07ac-4927-9814-233a2bc122ce','It has no local extrema','אין לה קיצון מקומי');
INSERT INTO Translation VALUES('c4b6067b-b11d-44b9-b5d8-3e134ac8fd50','It is always differentiable','היא תמיד דיפרנציאבילית');
INSERT INTO Translation VALUES('496416d1-65ab-41c2-9710-f80c027346f5','A monotonically increasing function satisfies f(x₁) ≤ f(x₂) whenever x₁ ≤ x₂.','פונקציה עולה מונוטונית מקיימת f(x₁) ≤ f(x₂) כאשר x₁ ≤ x₂.');
INSERT INTO Translation VALUES('5c3d92e0-19fb-404c-b1eb-3eb3b5095cc1','Which condition ensures that a function has a unique local extremum on an open interval?','איזה תנאי מבטיח שלפונקציה יש קיצון מקומי יחיד על קטע פתוח?');
INSERT INTO Translation VALUES('93082228-325c-4838-908d-7a42537f05aa','The function is unimodal','הפונקציה היא חד-מודלית');
INSERT INTO Translation VALUES('7e81ebf0-8094-4b1c-9485-c143bcf08045','The function is continuous','הפונקציה רציפה');
INSERT INTO Translation VALUES('f6d96a2a-6316-4a32-aaa0-50ea3cc1f9a5','The function is bounded','הפונקציה חסומה');
INSERT INTO Translation VALUES('187ae074-bea2-4f8e-8a91-7970eeb19df9','The function is linear','הפונקציה לינארית');
INSERT INTO Translation VALUES('794ef290-5594-411a-8f8f-78a602703ad3','A unimodal function on an open interval can have at most one local maximum or minimum.','פונקציה חד-מודלית על קטע פתוח יכולה לקבל לכל היותר מקסימום או מינימום מקומי אחד.');
INSERT INTO Translation VALUES('6a2a9307-df60-4be4-bb3b-22a49c5745a2','What characterizes a bounded sequence?','מה מאפיין סדרה חסומה?');
INSERT INTO Translation VALUES('2827f8f1-9733-4731-b965-c2b98c7cb947','There exist real numbers M and m such that m ≤ aₙ ≤ M for all n','קיימים מספרים ממשיים M ו-m כך ש m ≤ aₙ ≤ M לכל n');
INSERT INTO Translation VALUES('8c5d8b8b-0c98-4183-9883-f6ec730beb8d','The sequence converges to zero','הסדרה מתכנסת לאפס');
INSERT INTO Translation VALUES('8c9bc890-d27d-4bd6-8157-b981f44d95e0','All terms are positive','כל האיברים חיוביים');
INSERT INTO Translation VALUES('7294ba1c-47d2-4b8d-9d8d-800f23610594','The sequence is monotonic','הסדרה מונוטונית');
INSERT INTO Translation VALUES('2902f241-a1de-4653-bcc3-4c90236cff7c','Every convergent sequence is bounded.','כל סדרה מתכנסת היא חסומה.');
INSERT INTO Translation VALUES('2877525b-87ed-4caf-b8e7-83c98c970dbf','If {aₙ} and {bₙ} are sequences where aₙ ≤ bₙ for all n, and both converge, what can we say about their limits?','אם {aₙ} ו-{bₙ} הן סדרות כאשר aₙ ≤ bₙ לכל n, ושתיהן מתכנסות, מה ניתן לומר על הגבולות שלהן?');
INSERT INTO Translation VALUES('88df97a2-742e-4961-bd3d-0aac4bfc5449','lim aₙ ≤ lim bₙ','lim aₙ ≤ lim bₙ');
INSERT INTO Translation VALUES('760e19a8-d0c6-4ff2-80b4-f4e59a575614','lim aₙ < lim bₙ','lim aₙ < lim bₙ');
INSERT INTO Translation VALUES('e52a84b2-d14c-4864-b673-e4e892a2ec47','lim aₙ = lim bₙ','lim aₙ = lim bₙ');
INSERT INTO Translation VALUES('cc8f6a1f-3830-4071-b867-0867bb40bd4e','No relationship exists','אין קשר');
INSERT INTO Translation VALUES('02e4e17f-4862-47e8-919d-ea230b5a8f33','The inequality between sequences is preserved in the limit even if the sequences are strictly ordered.','אי-השוויון בין סדרות נשמר בגבול גם אם הסדרות מסודרות בסדר חזק.');
INSERT INTO Translation VALUES('adc981c9-ca7b-45cf-9bcf-3e88a7c593cf','What does the Squeeze Theorem (Sandwich Theorem) state?','מה קובע משפט הסנדוויץ (משפט הדחיקה)?');
INSERT INTO Translation VALUES('451111a0-b2aa-420e-98cd-af1c84f69095','If aₙ ≤ bₙ ≤ cₙ and lim aₙ = lim cₙ = L, then lim bₙ = L','אם aₙ ≤ bₙ ≤ cₙ ו lim aₙ = lim cₙ = L, אז lim bₙ = L');
INSERT INTO Translation VALUES('dd145b49-117e-4df2-8bbc-83fb81712d23','The middle sequence always converges faster','הסדרה האמצעית תמיד מתכנסת מהר יותר');
INSERT INTO Translation VALUES('3202b076-99f7-4f7e-848c-8af88344b44c','Three sequences must have the same limit','שלוש סדרות חייבות לקבל אותו גבול');
INSERT INTO Translation VALUES('41391a7f-53eb-4c11-b1c3-b4ff571a90c4','Bounded sequences are squeezed','סדרות חסומות נדחקות');
INSERT INTO Translation VALUES('1e8c84ee-d336-4c92-9c4d-ffcd8a2063f4','The Squeeze Theorem can be applied even if the inequalities hold only from some index onwards.','ניתן ליישם את משפט הדחיקה גם אם אי-השוויונים מתקיימים רק מאינדקס מסוים ואילך.');
INSERT INTO Translation VALUES('d4f04a6b-ed63-4a71-bed7-42a49d5d9ce0','Which property defines a monotone sequence?','איזו תכונה מגדירה סדרה מונוטונית?');
INSERT INTO Translation VALUES('e913d6ac-f2d5-4dad-bb21-f19c2bdb8ecd','Either increasing for all n: aₙ₊₁ ≥ aₙ, or decreasing for all n: aₙ₊₁ ≤ aₙ','או עולה לכל n: aₙ₊₁ ≥ aₙ, או יורדת לכל n: aₙ₊₁ ≤ aₙ');
INSERT INTO Translation VALUES('ce5f5db4-6417-40cd-aa48-eb66f91882cb','The sequence has a finite limit','לסדרה יש גבול סופי');
INSERT INTO Translation VALUES('10b2934d-dddb-48fe-944e-e8a6ea6eb46b','All terms have the same sign','לכל האיברים יש אותו סימן');
INSERT INTO Translation VALUES('5260119a-a3eb-4f74-9dcf-7550d513f186','The sequence converges','הסדרה מתכנסת');
INSERT INTO Translation VALUES('71b49399-d5e9-4afe-b3d9-61b94487739b','Every bounded monotone sequence converges.','כל סדרה מונוטונית חסומה מתכנסת.');
INSERT INTO Translation VALUES('0c71bacc-f2fc-467d-a664-d36138035b8d','What is a subsequence?','מהי תת-סדרה?');
INSERT INTO Translation VALUES('8cfc641f-ecfd-464b-b439-fb4eb68227c8','A sequence {aₙₖ} where n₁ < n₂ < n₃ < ... and {aₙ} is the original sequence','סדרה {aₙₖ} כאשר n₁ < n₂ < n₃ < ... ו-{aₙ} היא הסדרה המקורית');
INSERT INTO Translation VALUES('daa23faf-ed48-44f0-9a15-1ba06d56b0b1','A sequence with fewer terms','סדרה עם פחות איברים');
INSERT INTO Translation VALUES('4ca010e5-2467-420e-a5d9-6d48bfe9d072','A sequence that converges faster','סדרה שמתכנסת מהר יותר');
INSERT INTO Translation VALUES('13313e11-21fa-49af-b269-03e0003d3116','A finite sequence','סדרה סופית');
INSERT INTO Translation VALUES('b66013fb-ad2e-4f8b-aa11-667884ded639','Every subsequence of a convergent sequence converges to the same limit.','כל תת-סדרה של סדרה מתכנסת מתכנסת לאותו גבול.');
INSERT INTO Translation VALUES('773cc1d0-e7db-4abe-b743-899c5bac23c8','What is an infinite series?','מהו טור אינסופי?');
INSERT INTO Translation VALUES('a383dfba-ea54-485d-8d1e-2f19b1dd82dd','The sum ∑(n=1 to ∞) aₙ = a₁ + a₂ + a₃ + ...','הסכום ∑(n=1 to ∞) aₙ = a₁ + a₂ + a₃ + ...');
INSERT INTO Translation VALUES('2bd8c444-d180-470b-b691-5cdc3b577709','A sequence with infinitely many terms','סדרה עם אינסוף איברים');
INSERT INTO Translation VALUES('5cbf2bbe-e6fd-490e-8874-35ec4a8343ba','A function with infinite domain','פונקציה עם תחום אינסופי');
INSERT INTO Translation VALUES('5d3241c3-55bf-4269-8de2-5a563bbe18bc','An unbounded sequence','סדרה לא חסומה');
INSERT INTO Translation VALUES('a5b8e00b-2ee2-408f-9e9f-ccb7167d12be','A series converges if and only if the sequence of partial sums converges.','טור מתכנס אם ורק אם סדרת הסכומים החלקיים מתכנסת.');
INSERT INTO Translation VALUES('b44f938d-86ee-45bc-9b04-8d149219c7f3','What does the Integral Test state?','מה קובע מבחן האינטגרל?');
INSERT INTO Translation VALUES('c76880fd-148b-48d6-ab46-6052f94516a9','If f is positive, decreasing, and continuous, then ∑aₙ and ∫f(x)dx have the same convergence behavior','אם f חיובית, יורדת ורציפה, אז ל-∑aₙ ו-∫f(x)dx יש אותו התנהגות התכנסות');
INSERT INTO Translation VALUES('41129ca0-c4f4-417b-bdd1-17cf42118c02','Every series can be tested with integration','כל טור ניתן לבדוק עם אינטגרציה');
INSERT INTO Translation VALUES('05d47934-e9d3-4f41-967e-b579363711ca','Integrals always converge faster than series','אינטגרלים תמיד מתכנסים מהר יותר מטורים');
INSERT INTO Translation VALUES('e48dce33-ef2a-4d13-bf50-d78ebabdb07b','The integral gives the exact sum','האינטגרל נותן את הסכום המדויק');
INSERT INTO Translation VALUES('19de3c15-4400-4bcd-81b1-930ccc70596e','The Integral Test requires the function to be positive and decreasing.','מבחן האינטגרל דורש שהפונקציה תהיה חיובית ויורדת.');
INSERT INTO Translation VALUES('d7f3c40b-0965-486a-af5b-d9bdd1481c4d','What is the Limit Comparison Test used for?','למה משמש מבחן ההשוואה הגבולי?');
INSERT INTO Translation VALUES('9375404c-d2be-4c7d-8cf0-07c9f648c8e2','To determine convergence by comparing with a known series','לקבוע התכנסות על ידי השוואה לטור ידוע');
INSERT INTO Translation VALUES('8591fef2-3661-4332-8ad0-fa6f031cd19e','To find the exact sum of a series','למצוא את הסכום המדויק של טור');
INSERT INTO Translation VALUES('bc6428b4-df8e-4928-a7e5-336d38311a58','To calculate limits of sequences','לחשב גבולות של סדרות');
INSERT INTO Translation VALUES('608bc72f-7158-4ca8-b3c5-7324dee6a715','To test monotonicity','לבדוק מונוטוניות');
INSERT INTO Translation VALUES('dea41997-f1d9-41b1-a7c5-15613673bcb8','If lim(aₙ/bₙ) = L > 0 and finite, then ∑aₙ and ∑bₙ have the same convergence behavior.','אם lim(aₙ/bₙ) = L > 0 וסופי, אז ל-∑aₙ ו-∑bₙ יש אותה התנהגות התכנסות.');
INSERT INTO Translation VALUES('8f15757e-12cf-4f33-b1f7-3bd0057cd40c','What does the Ratio Test examine?','מה בודק מבחן היחס?');
INSERT INTO Translation VALUES('66b51046-e299-4ecc-adba-bc6bd9cca458','The limit of |aₙ₊₁/aₙ| as n approaches infinity','הגבול של |aₙ₊₁/aₙ| כאשר n שואף לאינסוף');
INSERT INTO Translation VALUES('e3396a59-2532-4be8-b7ec-3f51888b7417','The ratio of consecutive partial sums','היחס בין סכומים חלקיים עוקבים');
INSERT INTO Translation VALUES('9de95052-6616-4598-8944-b69b3a607a54','The ratio of terms to their indices','היחס בין איברים לאינדקסים שלהם');
INSERT INTO Translation VALUES('a4ae4fbe-919f-4f3f-9e7d-5977043778a9','The limit of the sequence itself','הגבול של הסדרה עצמה');
INSERT INTO Translation VALUES('8c640ee9-ba38-49fe-8ab5-0f4d95c850fb','If lim|aₙ₊₁/aₙ| < 1, then the series ∑aₙ converges absolutely.','אם lim|aₙ₊₁/aₙ| < 1, אז הטור ∑aₙ מתכנס בהחלט.');
INSERT INTO Translation VALUES('ecb05ebb-e282-4ed1-a2c2-3c5b32e8ab77','How can functions be represented as power series?','איך ניתן לייצג פונקציות כטורי חזקות?');
INSERT INTO Translation VALUES('a0812895-dd17-421c-8224-780b4eadffbb','As f(x) = ∑(n=0 to ∞) aₙ(x-c)ⁿ within the radius of convergence','כ f(x) = ∑(n=0 to ∞) aₙ(x-c)ⁿ בתוך רדיוס ההתכנסות');
INSERT INTO Translation VALUES('0ef369ed-4347-48b7-9f30-a21ca120de62','Only polynomial functions can be represented','רק פונקציות פולינומיות ניתנות לייצוג');
INSERT INTO Translation VALUES('0942ee34-b250-4930-9af5-b2bb5a6bd4a4','As finite sums only','כסכומים סופיים בלבד');
INSERT INTO Translation VALUES('4fccee8d-5a0e-4edf-80b4-3690c45c6d2d','Using trigonometric functions only','באמצעות פונקציות טריגונומטריות בלבד');
INSERT INTO Translation VALUES('24edf076-7318-4654-b847-5085e40f014e','Power series representations are unique when they exist.','ייצוגי טורי חזקות הם יחידים כאשר הם קיימים.');
INSERT INTO Translation VALUES('84ef0001-1f88-4c7f-b286-10355a72b1f1','What properties do power series inherit regarding continuity and differentiability?','אילו תכונות יורשים טורי חזקות בנוגע לרציפות ודיפרנציאביליות?');
INSERT INTO Translation VALUES('020b6009-1cfc-43a9-bba6-847e08613317','They can be differentiated and integrated term by term within the radius of convergence','ניתן לגזור ולהטמיע אותם איבר איבר בתוך רדיוס ההתכנסות');
INSERT INTO Translation VALUES('230b2284-18fb-4b30-b19a-93ed96743f90','They are always discontinuous','הם תמיד לא רציפים');
INSERT INTO Translation VALUES('6079670c-aed5-4e63-b521-ecbfddb082d0','They cannot be differentiated','לא ניתן לגזור אותם');
INSERT INTO Translation VALUES('168da523-7679-42e3-b3dd-6645ed94c513','Integration changes the radius of convergence','אינטגרציה משנה את רדיוס ההתכנסות');
INSERT INTO Translation VALUES('a8ec8b85-45fc-488b-b961-76cb853b5f88','A power series is infinitely differentiable within its radius of convergence.','טור חזקות ניתן לגזירה אינסופית בתוך רדיוס ההתכנסות שלו.');
INSERT INTO Translation VALUES('393a3e0e-1957-40f3-910b-8729a355fbe2','What is the relationship between derivatives of inverse functions?','מה הקשר בין נגזרות של פונקציות הפוכות?');
INSERT INTO Translation VALUES('d39cc965-0040-4102-85f2-f6a01fdd1a9f','(f⁻¹)′(y) = 1/f′(f⁻¹(y))','(f⁻¹)′(y) = 1/f′(f⁻¹(y))');
INSERT INTO Translation VALUES('87345848-49f4-43cd-b423-7ee7895f2e73','(f⁻¹)′(y) = f′(y)','(f⁻¹)′(y) = f′(y)');
INSERT INTO Translation VALUES('7a9d21b1-c51c-4461-a882-1a0a79271332','(f⁻¹)′(y) = -f′(y)','(f⁻¹)′(y) = -f′(y)');
INSERT INTO Translation VALUES('c90e2cfe-2ef3-4d08-a616-3404b2b650a1','They are unrelated','הם לא קשורים');
INSERT INTO Translation VALUES('4c754430-4b6f-477c-be7e-e7cf14116dea','The derivative of an inverse function exists wherever the original function is differentiable with non-zero derivative.','הנגזרת של פונקציה הפוכה קיימת בכל מקום שבו הפונקציה המקורית דיפרנציאבילית עם נגזרת לא-אפס.');
INSERT INTO Translation VALUES('b7d0f146-bb75-476d-be32-aa368517b552','Which statement characterizes monotone functions?','איזה משפט מאפיין פונקציות מונוטוניות?');
INSERT INTO Translation VALUES('4003e1d0-f148-48c2-80ab-d8825ed9e57c','They are either entirely non-decreasing or non-increasing','הן או לא יורדות או לא עולות לחלוטין');
INSERT INTO Translation VALUES('df196fb0-d2c6-459a-8b8d-1ad229f46148','They always have derivatives','תמיד יש להן נגזרות');
INSERT INTO Translation VALUES('d22c235e-0fc6-4907-a5fe-c2af788d21f6','They are continuous everywhere','הן רציפות בכל מקום');
INSERT INTO Translation VALUES('455b0708-6b77-4b64-8537-23073680eb65','They have bounded ranges','יש להן תחומי ערכים חסומים');
INSERT INTO Translation VALUES('532af462-f68e-47aa-b956-38fa5486e380','A strictly monotone function is always injective (one-to-one).','פונקציה מונוטונית ממש היא תמיד חד-חד-ערכית.');
INSERT INTO Translation VALUES('f228bde4-978c-4a23-94eb-543d790f66e9','What method is used for integrating rational functions?','איזו שיטה משמשת לאינטגרציה של פונקציות רציונליות?');
INSERT INTO Translation VALUES('b9d7372c-f9c8-4cb2-9720-9e5737355798','Partial fraction decomposition','פירוק לשברים חלקיים');
INSERT INTO Translation VALUES('e6f3be12-bcbd-4958-9bc3-6a82d7055c6d','Integration by parts only','אינטגרציה בחלקים בלבד');
INSERT INTO Translation VALUES('e4597be8-ed76-4e13-a618-f4189b9b5216','Substitution method only','שיטת החלפה בלבד');
INSERT INTO Translation VALUES('26dae1bd-c39e-4bee-81ab-2288b9507a68','Direct integration','אינטגרציה ישירה');
INSERT INTO Translation VALUES('c5c3cf50-707d-41f0-b6d8-db1e519d5c30','Every rational function can be integrated using elementary functions.','כל פונקציה רציונלית ניתנת לאינטגרציה באמצעות פונקציות אלמנטריות.');
INSERT INTO Translation VALUES('829247d6-401f-48e1-9213-388b7b3fb303','What are Riemann sums used for?','למה משמשים סכומי רימן?');
INSERT INTO Translation VALUES('f4a5bd0a-e45d-4651-b81f-92b92aa57983','To approximate definite integrals using rectangles','להעריך אינטגרלים מסוימים באמצעות מלבנים');
INSERT INTO Translation VALUES('ae466c22-d6c4-4d03-974b-7f60d27a07d5','To find antiderivatives','למצוא פונקציות קדומות');
INSERT INTO Translation VALUES('cbf2d73b-ab00-4cf5-84e1-4c4ca66ded9b','To calculate limits only','לחשב גבולות בלבד');
INSERT INTO Translation VALUES('00f0005f-8925-4e07-823a-342d13c705e1','To prove continuity','להוכיח רציפות');
INSERT INTO Translation VALUES('ad9b433a-91c5-4517-b837-7e4bb8296a2a','The definite integral is the limit of Riemann sums as the partition becomes finer.','האינטגרל המסוים הוא הגבול של סכומי רימן כאשר החלוקה נעשית עדינה יותר.');
INSERT INTO Translation VALUES('b876c5cc-7044-4758-816c-6939a4117626','Which condition characterizes Riemann integrable functions?','איזה תנאי מאפיין פונקציות הניתנות לאינטגרציה לפי רימן?');
INSERT INTO Translation VALUES('6b04cb81-1bcd-4326-b86a-baa5d1542f6b','The set of discontinuities has measure zero','קבוצת נקודות אי-הרציפות היא ממידה אפס');
INSERT INTO Translation VALUES('acf95ad6-91b2-4439-abf1-e0ffc1688dcb','The function is continuous everywhere','הפונקציה רציפה בכל מקום');
INSERT INTO Translation VALUES('f56b5a2b-3940-49f7-bd69-29f76feadfb8','The function is bounded and monotonic','הפונקציה חסומה ומונוטונית');
INSERT INTO Translation VALUES('871f02b6-4251-4ea8-a710-4b10685b57ce','The function has finitely many discontinuities','לפונקציה יש מספר סופי של אי-רציפויות');
INSERT INTO Translation VALUES('af854c5b-a4b9-476c-8574-8f3b434638c1','Every continuous function on a closed interval is Riemann integrable.','כל פונקציה רציפה על קטע סגור ניתנת לאינטגרציה לפי רימן.');
INSERT INTO Translation VALUES('5d1dd1b1-7ae3-439d-8d45-f37c7e35e003','If f(x) ≤ g(x) on [a,b], what can we say about their integrals?','אם f(x) ≤ g(x) על [a,b], מה ניתן לומר על האינטגרלים שלהן?');
INSERT INTO Translation VALUES('893f692b-5943-4640-aad0-bed334900dd0','∫f(x)dx ≤ ∫g(x)dx','∫f(x)dx ≤ ∫g(x)dx');
INSERT INTO Translation VALUES('b9be2216-ce78-44af-bedb-9865c8c8741c','∫f(x)dx > ∫g(x)dx','∫f(x)dx > ∫g(x)dx');
INSERT INTO Translation VALUES('ebfe8221-094e-4627-8001-f418780cf7a6','∫f(x)dx = ∫g(x)dx','∫f(x)dx = ∫g(x)dx');
INSERT INTO Translation VALUES('6b8bd7b6-aca2-4875-974b-4904daa8b3be','No relationship exists','אין קשר');
INSERT INTO Translation VALUES('1081247e-9989-40e6-8b8e-82c8c9c72d8c','The inequality ∫|f(x)|dx ≥ |∫f(x)dx| always holds.','אי-השוויון ∫|f(x)|dx ≥ |∫f(x)dx| תמיד מתקיים.');
INSERT INTO Translation VALUES('a18c403d-562f-4283-8cc2-16331f0f8f34','What does the First Fundamental Theorem of Calculus state?','מה קובע המשפט היסודי הראשון של החשבון האינפיניטיסימלי?');
INSERT INTO Translation VALUES('1de32908-42fe-4efe-b127-4f65a7818d31','If F(x) = ∫f(t)dt from a to x, then F′(x) = f(x)','אם F(x) = ∫f(t)dt מ-a עד x, אז F′(x) = f(x)');
INSERT INTO Translation VALUES('ad736b1d-1560-4dee-8d64-31b8e93e1e05','Every function has an antiderivative','לכל פונקציה יש פונקציה קדומה');
INSERT INTO Translation VALUES('9cb29a62-8140-4a36-b5e8-563f8ee754a4','Integration and differentiation are inverse operations','אינטגרציה וגזירה הן פעולות הפוכות');
INSERT INTO Translation VALUES('68cccfcd-3b23-480e-b680-701f07881b26','Definite integrals equal indefinite integrals','אינטגרלים מסוימים שווים לאינטגרלים בלתי מסוימים');
INSERT INTO Translation VALUES('bef3a0ab-f31b-4700-a78c-579aea9bb4f1','The antiderivative obtained from the First Fundamental Theorem is continuous.','הפונקציה הקדומה שמתקבלת מהמשפט היסודי הראשון היא רציפה.');
INSERT INTO Translation VALUES('a74cb2df-301a-4684-a7f1-a11ca8493ddb','What does the Mean Value Theorem for integrals guarantee?','מה מבטיח משפט הערך הממוצע לאינטגרלים?');
INSERT INTO Translation VALUES('88f82cfa-39c4-4ad7-a912-4fc73c7a5469','There exists c such that the integral equals f(c) times the interval length','קיים c כך שהאינטגרל שווה ל-f(c) כפול אורך הקטע');
INSERT INTO Translation VALUES('91fcb78a-a0c7-4256-8692-03566adc6833','The integral equals the average value','האינטגרל שווה לערך הממוצע');
INSERT INTO Translation VALUES('ef7419e4-6783-432d-9e23-b63c8082758e','Every function achieves its mean value','כל פונקציה משיגה את הערך הממוצע שלה');
INSERT INTO Translation VALUES('2b0ea86f-69c2-4905-830a-fced5c980b88','Continuous functions are integrable','פונקציות רציפות ניתנות לאינטגרציה');
INSERT INTO Translation VALUES('70a5d797-ecdc-42a8-a545-8cb5163ec307','The Mean Value Theorem for integrals requires the function to be continuous.','משפט הערך הממוצע לאינטגרלים דורש שהפונקציה תהיה רציפה.');
INSERT INTO Translation VALUES('952b8a01-61a8-4617-80ed-98fa477af86a','When is the substitution method for integration most effective?','מתי שיטת ההחלפה לאינטגרציה היא הכי יעילה?');
INSERT INTO Translation VALUES('bb4e3cd3-f758-409e-b0c1-00f33fe04458','When the integrand contains a function and its derivative','כאשר המטמיע מכיל פונקציה והנגזרת שלה');
INSERT INTO Translation VALUES('dbfe3685-abf2-4841-b586-696e551ef623','Only for polynomial functions','רק עבור פונקציות פולינומיות');
INSERT INTO Translation VALUES('133bd1ae-1d71-4723-9198-dbba15ec99d1','When the function is continuous','כאשר הפונקציה רציפה');
INSERT INTO Translation VALUES('f0ecaaa3-583d-4150-8320-3152c8cd8e78','For all rational functions','עבור כל הפונקציות הרציונליות');
INSERT INTO Translation VALUES('d3787dc3-8648-4a30-b06b-2912223ef517','The substitution requires the derivative to be present in the integral.','ההחלפה דורשת שהנגזרת תהיה נוכחת באינטגרל.');
INSERT INTO Translation VALUES('fb8da5b8-877f-40c1-b500-19ad97bb4566','What does the Second Fundamental Theorem of Calculus state?','מה קובע המשפט היסודי השני של החשבון האינפיניטיסימלי?');
INSERT INTO Translation VALUES('1a3f7152-229a-4d82-a264-786ebba92dfe','The definite integral equals the antiderivative evaluated at endpoints','האינטגרל המסוים שווה לפונקציה הקדומה מוערכת בקצוות');
INSERT INTO Translation VALUES('4b7ffd74-55ff-4a6d-a042-7d866558a81e','Every continuous function is differentiable','כל פונקציה רציפה ניתנת לגזירה');
INSERT INTO Translation VALUES('df5879e2-a988-4cba-a5cd-74f1af421a9b','Derivatives exist everywhere','נגזרות קיימות בכל מקום');
INSERT INTO Translation VALUES('4b919390-7ecf-4d9e-aa16-0365bb6be964','Integration preserves continuity','אינטגרציה שומרת על רציפות');
INSERT INTO Translation VALUES('bfd9522c-8697-45c5-98a6-86770d920b50','The Second Fundamental Theorem provides a method to evaluate definite integrals without limits.','המשפט היסודי השני מספק שיטה להעריך אינטגרלים מסוימים ללא גבולות.');
INSERT INTO Translation VALUES('ae1400a8-3638-4ce6-b06a-df6f4690e1f9','What characterizes an improper integral?','מה מאפיין אינטגרל לא אמיתי?');
INSERT INTO Translation VALUES('a882970f-9985-4401-a81a-5921e8686c74','The interval is infinite or the integrand is unbounded','הקטע אינסופי או שהמטמיע אינו חסום');
INSERT INTO Translation VALUES('04874a40-cfd3-42ed-833c-ac38bc87a679','The function is not continuous','הפונקציה אינה רציפה');
INSERT INTO Translation VALUES('bd723867-c886-42b7-8a61-cd4092a230bf','The antiderivative does not exist','הפונקציה הקדומה לא קיימת');
INSERT INTO Translation VALUES('d2e159a3-7c0a-43cd-b899-380932ec9ce2','The function is irrational','הפונקציה אי-רציונלית');
INSERT INTO Translation VALUES('d166f54f-08ba-4ee2-8a4e-277a8edfabc3','Improper integrals are evaluated using limits of proper integrals.','אינטגרלים לא אמיתיים מוערכים באמצעות גבולות של אינטגרלים אמיתיים.');
INSERT INTO Translation VALUES('2c25ded8-6bf8-40fa-ab35-acc01c95ed80','What tests are used for convergence of improper integrals?','אילו מבחנים משמשים לבדיקת התכנסות של אינטגרלים לא אמיתיים?');
INSERT INTO Translation VALUES('3e90639d-f250-411a-ad18-06a3e4b5631a','Comparison test, limit comparison test, and p-test','מבחן ההשוואה, מבחן ההשוואה הגבולי ומבחן p');
INSERT INTO Translation VALUES('de964998-22cf-45de-984a-a0a693af853c','Only the ratio test','רק מבחן היחס');
INSERT INTO Translation VALUES('1ffac875-712f-48e5-ade7-caa6b53ec6a0','Integration by parts only','רק אינטגרציה בחלקים');
INSERT INTO Translation VALUES('0d221f8f-1c09-45b3-a602-569c2cbfb4c3','Direct evaluation only','רק הערכה ישירה');
INSERT INTO Translation VALUES('5724fe20-99ec-4b37-9589-a303b6004710','The p-test states that the integral of 1/x^p from 1 to infinity converges if and only if p > 1.','מבחן p קובע שהאינטגרל של 1/x^p מ-1 עד אינסוף מתכנס אם ורק אם p > 1.');
INSERT INTO Translation VALUES('451a2498-f631-4803-9e1d-6a3da4a4bd5c','How is a finite sequence different from an infinite sequence?','איך סדרה סופית שונה מסדרה אינסופית?');
INSERT INTO Translation VALUES('fa385d93-911d-4dcd-a039-b609b8482439','A finite sequence has finitely many terms','לסדרה סופית יש מספר סופי של איברים');
INSERT INTO Translation VALUES('6ce6cf68-9fd1-4a5c-8154-3796e38d6021','Finite sequences always converge','סדרות סופיות תמיד מתכנסות');
INSERT INTO Translation VALUES('86455b59-94d2-4415-bf3f-b942495aaa32','Only infinite sequences have limits','רק לסדרות אינסופיות יש גבולות');
INSERT INTO Translation VALUES('6fd70b0f-6ebe-4268-b273-a672ba68f68c','The terms have different properties','לאיברים יש תכונות שונות');
INSERT INTO Translation VALUES('02b950f3-8ea1-48cc-a379-b11ee0324efe','Every finite sequence is bounded.','כל סדרה סופית היא חסומה.');
INSERT INTO Translation VALUES('b7d5802f-7faf-447c-808e-2c1772acb1d0','What are the equivalent definitions of the limit of a sequence?','מהן ההגדרות השקולות לגבול של סדרה?');
INSERT INTO Translation VALUES('44755462-e9ee-4d63-88f8-e34ae4110c36','Epsilon-N definition and convergence to a point','הגדרת אפסילון-N והתכנסות לנקודה');
INSERT INTO Translation VALUES('6d0f528a-642c-4b93-8165-42f3fdccd83e','Only the formal definition exists','קיימת רק ההגדרה הפורמלית');
INSERT INTO Translation VALUES('230c22f4-6879-4830-b439-8bfed0af5788','Graphical and algebraic definitions','הגדרות גרפיות ואלגבריות');
INSERT INTO Translation VALUES('152364c6-843a-4d36-9c4d-3c7257915829','Monotonicity and boundedness','מונוטוניות וחסימות');
INSERT INTO Translation VALUES('46a337aa-cdfd-449e-a580-6c3b5e2eab29','The limit of a sequence, if it exists, is unique.','הגבול של סדרה, אם הוא קיים, הוא יחיד.');
INSERT INTO Translation VALUES('cda7dc11-4f8d-4857-bf7f-a2d28985cd78','How do you prove the existence of a limit?','איך מוכיחים קיום של גבול?');
INSERT INTO Translation VALUES('989742f8-5fc4-45cf-9703-ace55737e494','Show that for every epsilon there exists N such that terms are within epsilon of L','להראות שלכל אפסילון קיים N כך שהאיברים נמצאים במרחק אפסילון מ-L');
INSERT INTO Translation VALUES('677f3818-1ff2-4df2-8119-2f3ad9daa68d','Calculate the terms of the sequence','לחשב את איברי הסדרה');
INSERT INTO Translation VALUES('f8f339a4-cddf-4d15-adf6-ac38e62f502f','Show the sequence is bounded','להראות שהסדרה חסומה');
INSERT INTO Translation VALUES('b7fd7e0c-4211-4c69-aace-9f4994104309','Prove continuity','להוכיח רציפות');
INSERT INTO Translation VALUES('5ee4fad1-d38c-41d9-a74d-3c3e90180a61','To prove non-existence of a limit, you can show the sequence has two convergent subsequences with different limits.','כדי להוכיח אי-קיום של גבול, ניתן להראות שלסדרה יש שתי תת-סדרות מתכנסות עם גבולות שונים.');
INSERT INTO Translation VALUES('6da1d6e4-157d-4da7-b91b-cb54343ea76c','What are the basic limit theorems for sequences?','מהם משפטי הגבול הבסיסיים לסדרות?');
INSERT INTO Translation VALUES('b6dbba7f-9c30-4f9c-9b93-5fce34336f8a','Limits of sums, products, and quotients follow arithmetic rules','גבולות של סכומים, מכפלות ומנות פועלים לפי כללי חשבון');
INSERT INTO Translation VALUES('a78fae2d-fcbe-4b8d-84c7-baa1ffdf9f64','All sequences have limits','לכל הסדרות יש גבולות');
INSERT INTO Translation VALUES('178f73a3-7145-4db7-875d-5796962e6044','Limits are always finite','גבולות תמיד סופיים');
INSERT INTO Translation VALUES('73198ddf-593d-49e6-a79b-b1c48e4345ac','Only bounded sequences have limits','רק לסדרות חסומות יש גבולות');
INSERT INTO Translation VALUES('1a728eb1-e06f-4a98-b89d-b64508445567','If sequences converge to A and B respectively, then their sum converges to A + B.','אם סדרות מתכנסות ל-A ו-B בהתאמה, אז הסכום שלהן מתכנס ל-A + B.');
INSERT INTO Translation VALUES('64c3711b-2ab8-4974-8cdb-80939e9ae132','What does it mean for a sequence to diverge to infinity?','מה המשמעות של כך שסדרה מתבדרת לאינסוף?');
INSERT INTO Translation VALUES('2fa66a15-39e9-485e-bc81-fdde4a5ab4b9','For every M there exists N such that terms exceed M for all n > N','לכל M קיים N כך שהאיברים עולים על M לכל n > N');
INSERT INTO Translation VALUES('843aff84-8243-481b-9c36-f4d1579d62ad','The sequence increases without bound','הסדרה עולה ללא גבול');
INSERT INTO Translation VALUES('a278bf1d-6f87-4953-a735-4ff45cb2b716','All terms are positive','כל האיברים חיוביים');
INSERT INTO Translation VALUES('8c1db386-af45-4a1c-b82e-4fcbb2d70faf','The sequence has no pattern','לסדרה אין תבנית');
INSERT INTO Translation VALUES('179d8436-9593-4666-ab9c-f1eab8cf78af','A sequence can diverge to positive infinity, negative infinity, or oscillate without limit.','סדרה יכולה להתבדר לאינסוף חיובי, אינסוף שלילי, או להתנודד ללא גבול.');
INSERT INTO Translation VALUES('92f9f46b-1761-4c5d-ab9a-41e33c8e834f','What characterizes further convergence to infinity?','מה מאפיין התכנסות נוספת לאינסוף?');
INSERT INTO Translation VALUES('8d5cd021-5401-4628-9267-bec4019ad747','Advanced concepts like rates of divergence and comparison','מושגים מתקדמים כמו קצבי התבדרות והשוואה');
INSERT INTO Translation VALUES('a493a624-a115-455a-93b9-f5bd260e175b','Only positive sequences','רק סדרות חיוביות');
INSERT INTO Translation VALUES('f659ee41-1ea9-46d5-80e2-8cf4298e2dc9','Linear growth patterns','תבניות צמיחה לינאריות');
INSERT INTO Translation VALUES('9f8b20e0-6efb-4001-af8d-9b9aa40f23b0','Finite upper bounds','חסמים עליונים סופיים');
INSERT INTO Translation VALUES('6ed30382-7097-4f86-83e2-47eeb4ec3d38','Different sequences can diverge to infinity at different rates.','סדרות שונות יכולות להתבדר לאינסוף בקצבים שונים.');
INSERT INTO Translation VALUES('84972218-1b6d-4373-926e-855a3edc0047','What additional properties do bounded sequences have?','אילו תכונות נוספות יש לסדרות חסומות?');
INSERT INTO Translation VALUES('a30f143e-a77c-4ca7-a213-c413d56e00a5','Every bounded sequence has a convergent subsequence','לכל סדרה חסומה יש תת-סדרה מתכנסת');
INSERT INTO Translation VALUES('f1b4894b-5dd9-4793-a22f-56551821d68b','All bounded sequences converge','כל הסדרות החסומות מתכנסות');
INSERT INTO Translation VALUES('b9f19470-a6c2-4997-9bd0-a38fee9452cf','Bounded sequences are monotonic','סדרות חסומות הן מונוטוניות');
INSERT INTO Translation VALUES('b3054c3e-ef97-4d8a-a211-5def45af7baa','They have finite ranges only','יש להן רק תחומי ערכים סופיים');
INSERT INTO Translation VALUES('d51f0e43-1b19-465d-af86-bd3b128fa56d','The Bolzano-Weierstrass theorem applies to bounded sequences.','משפט בולצאנו-ויירשטראס חל על סדרות חסומות.');
INSERT INTO Translation VALUES('7ece6e6f-37fa-46d5-a4bb-eb465af21ac1','How does the Squeeze Theorem apply to infinite limits?','איך משפט הסנדוויץ חל על גבולות אינסופיים?');
INSERT INTO Translation VALUES('d77f4f47-78ad-4711-9293-ded2ada0f742','If sequences are squeezed between bounds that both go to infinity, the middle sequence also goes to infinity','אם סדרות נדחקות בין חסמים ששניהם הולכים לאינסוף, הסדרה האמצעית גם הולכת לאינסוף');
INSERT INTO Translation VALUES('76beee8c-341c-4a3f-b062-460803844bf3','It only works for finite limits','זה עובד רק עבור גבולות סופיים');
INSERT INTO Translation VALUES('be0f7a0b-020d-42af-8cbe-7edf3e84b747','Infinite limits cannot be squeezed','לא ניתן לדחוק גבולות אינסופיים');
INSERT INTO Translation VALUES('f117ddee-92ae-4c48-8b81-a8b887b21472','The theorem becomes invalid','המשפט הופך לא תקף');
INSERT INTO Translation VALUES('bd18d076-63ae-46e6-b7de-a804ec465e5a','The Squeeze Theorem works for both finite and infinite limits.','משפט הסנדוויץ עובד הן עבור גבולות סופיים והן עבור גבולות אינסופיים.');
INSERT INTO Translation VALUES('35927504-b257-4f5a-abc6-54f5d05ee8f4','What additional properties characterize monotone sequences?','אילו תכונות נוספות מאפיינות סדרות מונוטוניות?');
INSERT INTO Translation VALUES('05ed0e89-b906-4025-b3e4-019cf58fd347','Bounded monotone sequences always converge','סדרות מונוטוניות חסומות תמיד מתכנסות');
INSERT INTO Translation VALUES('c4bf6cc2-1eb4-4aee-926b-1980c5cb38c5','They are always bounded','הן תמיד חסומות');
INSERT INTO Translation VALUES('167a0d02-e12f-4a92-8b2b-ade3356ba316','They converge faster than other sequences','הן מתכנסות מהר יותר מסדרות אחרות');
INSERT INTO Translation VALUES('82432164-7e49-4969-9e24-7b6d1170f39e','They have unique limits','יש להן גבולות יחידים');
INSERT INTO Translation VALUES('c50eddd9-490c-43a5-adb0-efefb5d34669','The Monotone Convergence Theorem is a fundamental result in analysis.','משפט ההתכנסות המונוטונית הוא תוצאה יסודית באנליזה.');
INSERT INTO Translation VALUES('93786167-0d6c-409a-bfcd-2c0ef8fbfd9f','What advanced properties do subsequences have?','אילו תכונות מתקדמות יש לתת-סדרות?');
INSERT INTO Translation VALUES('9b15599e-c477-4137-97f8-789fab91f5fd','Every sequence has a monotone subsequence','לכל סדרה יש תת-סדרה מונוטונית');
INSERT INTO Translation VALUES('26a3d087-fb95-4cef-8d41-19bfc33ef987','Subsequences are always shorter','תת-סדרות תמיד קצרות יותר');
INSERT INTO Translation VALUES('a42947df-60d2-4fe2-a46b-411fcc200a0d','They preserve all properties','הן שומרות על כל התכונות');
INSERT INTO Translation VALUES('5b556fe8-9961-4405-88b5-4c95a267cf75','They converge faster','הן מתכנסות מהר יותר');
INSERT INTO Translation VALUES('2d6b203c-eb04-461c-8aa8-e3c30dc48d58','Every bounded sequence has a convergent subsequence by the Bolzano-Weierstrass theorem.','לכל סדרה חסומה יש תת-סדרה מתכנסת לפי משפט בולצאנו-ויירשטראס.');
INSERT INTO Translation VALUES('240dacd8-d065-4b23-bf76-d37f048fbc6a','What characterizes the completion of subsequences theory?','מה מאפיין את השלמת תורת התת-סדרות?');
INSERT INTO Translation VALUES('91d4d6e6-a818-46fa-8e90-1bb3ba3c2b42','Advanced theorems about limit points and cluster points','משפטים מתקדמים על נקודות גבול ונקודות צבירה');
INSERT INTO Translation VALUES('4eca8de5-8831-43e5-a288-387c52fca548','Simple enumeration of subsequences','ספירה פשוטה של תת-סדרות');
INSERT INTO Translation VALUES('9dbcd0e8-add0-46ad-8164-1675ba8cddaf','Only finite subsequences','רק תת-סדרות סופיות');
INSERT INTO Translation VALUES('7bdc9bb9-71fd-401c-ab22-a920cd30435a','Sequential ordering only','רק סידור רציף');
INSERT INTO Translation VALUES('e37fc05a-3355-4115-93fc-1db9f659e2bd','Limit points and cluster points are fundamental concepts in subsequence theory.','נקודות גבול ונקודות צבירה הם מושגים יסודיים בתורת התת-סדרות.');
INSERT INTO Translation VALUES('9f542b17-ae5b-4d1c-8085-9d1aa69c0b76','What additional properties characterize infinite series?','אילו תכונות נוספות מאפיינות טורים אינסופיים?');
INSERT INTO Translation VALUES('d92feebc-e6a5-4800-991e-5eaab094be76','Convergence tests, rearrangements, and conditional convergence','מבחני התכנסות, סידורים מחדש והתכנסות מותנית');
INSERT INTO Translation VALUES('a1d895cf-f650-4c94-9f32-80a04a512d8c','Only absolute convergence matters','רק התכנסות מוחלטת חשובה');
INSERT INTO Translation VALUES('7cfbd53a-7cb7-4a99-9d9d-983cab310506','All series can be summed directly','כל הטורים ניתנים לסיכום ישיר');
INSERT INTO Translation VALUES('39278e95-12b1-4605-aae1-170f12b9abe4','Finite partial sums only','רק סכומים חלקיים סופיים');
INSERT INTO Translation VALUES('5ec803f4-6372-492b-8520-d52a54d75ba3','Rearrangement of terms can affect convergence for conditionally convergent series.','סידור מחדש של איברים יכול להשפיע על התכנסות לטורים מתכנסים מותנית.');
INSERT INTO Translation VALUES('33d4581e-67c6-4e3c-b110-c55b6bef7066','How does the Integral Test work in practice?','איך מבחן האינטגרל עובד בפועל?');
INSERT INTO Translation VALUES('3949bc23-7556-4288-a9af-5ed189a91979','Compare series convergence with improper integral convergence','השווה התכנסות טור עם התכנסות אינטגרל לא אמיתי');
INSERT INTO Translation VALUES('ba102c50-57f2-42a5-9bef-49382af34197','Integrate each term separately','אינטגרציה של כל איבר בנפרד');
INSERT INTO Translation VALUES('d5c9c6b5-ce11-4cfa-96d0-7ab72abed958','Use only definite integrals','שימוש רק באינטגרלים מסוימים');
INSERT INTO Translation VALUES('c9eb12ef-9aee-4846-b187-e452d18ced96','Apply to all types of series','החל על כל סוגי הטורים');
INSERT INTO Translation VALUES('5685713d-302a-4625-a8b5-1321bba178b6','The Integral Test requires the terms to be positive, decreasing, and continuous.','מבחן האינטגרל דורש שהאיברים יהיו חיוביים, יורדים ורציפים.');
INSERT INTO Translation VALUES('135125ba-2fc4-43fd-adc8-36ddd1dee7a5','What does the Comparison Test examine?','מה בודק מבחן ההשוואה?');
INSERT INTO Translation VALUES('5b5c6fad-e82d-44e0-a528-a56a818536fd','Whether a series converges by comparing with a known convergent or divergent series','האם טור מתכנס על ידי השוואה לטור מתכנס או מתבדר ידוע');
INSERT INTO Translation VALUES('4f1e9f87-2f3b-4dc0-9d7c-0537f8c6a0f4','The ratio between consecutive terms','היחס בין איברים עוקבים');
INSERT INTO Translation VALUES('370477b4-fc37-4f7d-b0a9-6c66b9e7cdc0','The absolute values only','רק הערכים המוחלטים');
INSERT INTO Translation VALUES('96866cce-e084-44eb-ae02-0c7b22ee9ea0','Integration possibilities','אפשרויות אינטגרציה');
INSERT INTO Translation VALUES('b91fd9e9-f3ac-4b32-9683-fd9df50d6d92','If 0 ≤ aₙ ≤ bₙ and Σbₙ converges, then Σaₙ also converges.','אם 0 ≤ aₙ ≤ bₙ ו-Σbₙ מתכנס, אז Σaₙ גם מתכנס.');
INSERT INTO Translation VALUES('ce8c3ebb-1e50-4944-b3cd-3c648ea5d513','How does the Limit Comparison Test work?','איך עובד מבחן ההשוואה הגבולי?');
INSERT INTO Translation VALUES('e0982d37-03dd-4887-8927-81cdc7a9338f','Examine the limit of the ratio of terms from two series','בחן את הגבול של היחס בין איברים משני טורים');
INSERT INTO Translation VALUES('86daafff-b8c2-4c9d-8c79-898982b387e1','Compare only the first few terms','השווה רק את האיברים הראשונים');
INSERT INTO Translation VALUES('eb255c95-9d73-4e30-832f-223aad1c122a','Use integration by parts','השתמש באינטגרציה בחלקים');
INSERT INTO Translation VALUES('e4d159a0-2c1c-46e2-bf95-7767357379aa','Apply the squeeze theorem','החל את משפט הסנדוויץ');
INSERT INTO Translation VALUES('974b5aec-c463-4580-ba1e-01c73a11d1a9','The Limit Comparison Test is often easier to apply than the direct Comparison Test.','מבחן ההשוואה הגבולי לעתים קרובות קל יותר ליישום מאשר מבחן ההשוואה הישיר.');
INSERT INTO Translation VALUES('b1ab9b5b-fd63-4803-ab09-f15a2e547212','What characterizes alternating series?','מה מאפיין טורים מתחלפים?');
INSERT INTO Translation VALUES('d22dc5ee-6918-41a7-944e-95ddd7ff6616','Terms alternate in sign and special convergence tests apply','האיברים מתחלפים בסימן ומבחני התכנסות מיוחדים חלים');
INSERT INTO Translation VALUES('47aa3092-4229-4cd0-84c1-84b7f33e2664','All terms are negative','כל האיברים שליליים');
INSERT INTO Translation VALUES('fc89611c-597a-4b0c-b5dc-68812fad3909','Only odd-indexed terms matter','רק איברים באינדקס אי-זוגי חשובים');
INSERT INTO Translation VALUES('eaffd493-184f-46aa-86c5-5c80b4bc5184','They never converge','הם אף פעם לא מתכנסים');
INSERT INTO Translation VALUES('7c584f08-f575-4832-8e9c-822598ce9263','The Alternating Series Test provides conditions for convergence of alternating series.','מבחן הטורים המתחלפים מספק תנאים להתכנסות של טורים מתחלפים.');
INSERT INTO Translation VALUES('d9a0df58-8bfb-4cfe-b8bb-a124fc9a0e3e','What is absolute convergence?','מהי התכנסות מוחלטת?');
INSERT INTO Translation VALUES('4e801886-fb00-4ce5-8f2c-450dc441bb92','A series Σaₙ converges absolutely if Σ|aₙ| converges','טור Σaₙ מתכנס מוחלט אם Σ|aₙ| מתכנס');
INSERT INTO Translation VALUES('23669e1d-4903-45a9-a942-c33c02e9723f','All terms are positive','כל האיברים חיוביים');
INSERT INTO Translation VALUES('7f1ee74d-68ba-4583-8ada-7c904a469a8a','The series converges very quickly','הטור מתכנס מהר מאוד');
INSERT INTO Translation VALUES('787e503c-08df-4254-a809-518cefb31a2e','No rearrangement is possible','אף סידור מחדש אינו אפשרי');
INSERT INTO Translation VALUES('dd4d9bfe-4872-475e-9210-e9bfaae5739b','Absolute convergence implies regular convergence.','התכנסות מוחלטת גוררת התכנסות רגילה.');
INSERT INTO Translation VALUES('1078a07f-7263-4620-9cba-6c7d6abc688f','How does the Ratio Test work for series?','איך עובד מבחן היחס לטורים?');
INSERT INTO Translation VALUES('77d118f9-d2c1-487a-9de3-84f17c7d26b8','Examine the limit of |aₙ₊₁/aₙ| to determine convergence','בחן את הגבול של |aₙ₊₁/aₙ| כדי לקבוע התכנסות');
INSERT INTO Translation VALUES('0c1f32dc-8e96-45a4-ae72-a0e310965674','Compare the sum with integrals','השווה את הסכום עם אינטגרלים');
INSERT INTO Translation VALUES('8da40c88-59a3-40bf-a07a-194e1547bbf0','Use only the first and last terms','השתמש רק באיבר הראשון והאחרון');
INSERT INTO Translation VALUES('b0719817-5e3a-4a41-8715-3640e561c0a1','Apply to geometric series only','החל רק על טורים גיאומטריים');
INSERT INTO Translation VALUES('f9fdccc2-820a-4f3f-b57e-ce50657b6045','If the limit in the Ratio Test equals 1, the test is inconclusive.','אם הגבול במבחן היחס שווה ל-1, המבחן אינו חד-משמעי.');
INSERT INTO Translation VALUES('9a2ee597-2c5e-476e-a546-c27e430a72ab','What does the Root Test examine?','מה בודק מבחן השורש?');
INSERT INTO Translation VALUES('fa2f0813-762d-4cce-90a8-ef64858a0b6e','The limit of the nth root of |aₙ| as n approaches infinity','הגבול של השורש ה-n של |aₙ| כאשר n שואף לאינסוף');
INSERT INTO Translation VALUES('3a57f1ff-0d15-4b1a-9906-a62d5057e305','Whether terms have rational roots','האם לאיברים יש שורשים רציונליים');
INSERT INTO Translation VALUES('6894c293-5502-4e6a-870c-d4dc27d62af0','The square root of the sum','השורש הריבועי של הסכום');
INSERT INTO Translation VALUES('d3e4d202-b575-42ff-923a-35762b318b01','Polynomial degree only','רק דרגת הפולינום');
INSERT INTO Translation VALUES('25940289-5e08-4240-9b1a-b7c128af65c8','The Root Test is particularly useful for series with exponential terms.','מבחן השורש שימושי במיוחד לטורים עם איברים אקספוננציאליים.');
INSERT INTO Translation VALUES('0f730db7-b557-48db-8e0d-81506c08cde2','What characterizes power series?','מה מאפיין טורי חזקות?');
INSERT INTO Translation VALUES('52cddb09-bab8-47d7-8ace-f0f4d1c8dc47','Series of the form Σaₙ(x-c)ⁿ with radius of convergence','טורים מהצורה Σaₙ(x-c)ⁿ עם רדיוס התכנסות');
INSERT INTO Translation VALUES('5b345b14-fb1f-4d6e-b305-801a6a2f44a9','Series with only positive terms','טורים עם איברים חיוביים בלבד');
INSERT INTO Translation VALUES('2db972db-905b-45ce-91dc-e261adc60353','Finite polynomial series','טורי פולינומים סופיים');
INSERT INTO Translation VALUES('59408cd8-6a25-4a38-bf3b-767aedf7c84a','Series that always converge','טורים שתמיד מתכנסים');
INSERT INTO Translation VALUES('f0392c45-594c-4df4-ba88-6592697f010c','Every power series has a radius of convergence.','לכל טור חזקות יש רדיוס התכנסות.');
INSERT INTO Translation VALUES('1b9f1f12-0cad-4b53-b6d6-bb8586b0628f','How can functions be represented as power series?','איך ניתן לייצג פונקציות כטורי חזקות?');
INSERT INTO Translation VALUES('28c3df2f-f82c-47ff-b370-5e53766ad703','Through Taylor series expansion around a point','באמצעות פיתוח טיילור סביב נקודה');
INSERT INTO Translation VALUES('dcbcc7ad-973e-4e7f-812e-07e50e04169f','Only polynomial functions can be represented','רק פונקציות פולינומיות ניתנות לייצוג');
INSERT INTO Translation VALUES('fc13e171-875b-4ed5-a306-3e9fc050e753','Using Fourier series only','באמצעות טורי פורייה בלבד');
INSERT INTO Translation VALUES('da5e1884-fbc0-4151-a41a-8942594ef371','Through integration only','באמצעות אינטגרציה בלבד');
INSERT INTO Translation VALUES('74f9ff62-469a-4b29-87bf-9353cd842f57','Taylor series provide local approximations of functions using power series.','טורי טיילור מספקים קירובים מקומיים של פונקציות באמצעות טורי חזקות.');
INSERT INTO Translation VALUES('353e1a0f-5f54-4acd-9e04-749682f5319a','What properties do power series inherit?','אילו תכונות יורשים טורי חזקות?');
INSERT INTO Translation VALUES('8761f04a-c445-47c1-a0f5-ad17008088f9','Term-by-term differentiation and integration within radius of convergence','גזירה ואינטגרציה איבר איבר בתוך רדיוס ההתכנסות');
INSERT INTO Translation VALUES('d2a9e100-2739-42d6-bb95-ff47de842327','Always continuous everywhere','תמיד רציפים בכל מקום');
INSERT INTO Translation VALUES('40514c69-d5ce-484d-b5db-0f632a6d1df0','Never differentiable','אף פעם לא דיפרנציאבילים');
INSERT INTO Translation VALUES('4d649cf1-7923-41e3-8905-b88e2fb81cde','Only algebraic operations','רק פעולות אלגבריות');
INSERT INTO Translation VALUES('24068818-41b4-463c-a199-e2871d40aaeb','Power series can be differentiated term by term within their radius of convergence.','ניתן לגזור טורי חזקות איבר איבר בתוך רדיוס ההתכנסות שלהם.');
INSERT INTO Translation VALUES('9d08a54b-4e76-4b92-90cc-3bad4cab638c','What characterizes improper integrals of unbounded functions?','מה מאפיין אינטגרלים לא אמיתיים של פונקציות לא חסומות?');
INSERT INTO Translation VALUES('4579f584-a1c6-4b4f-bb46-f9a4306f9771','The integrand has vertical asymptotes or infinite discontinuities','למטמיע יש אסימפטוטות אנכיות או אי-רציפות אינסופיות');
INSERT INTO Translation VALUES('7c01ddc8-98eb-4511-83b3-9bc1073f040b','The interval is always infinite','הקטע תמיד אינסופי');
INSERT INTO Translation VALUES('28f5caa3-7d0c-4633-b149-ee18ba87e289','Integration is impossible','אינטגרציה בלתי אפשרית');
INSERT INTO Translation VALUES('dbc85fae-debf-4203-9069-7c60e06e306e','Only positive functions qualify','רק פונקציות חיוביות כשירות');
INSERT INTO Translation VALUES('a167e1d7-2645-4c4e-a220-c2beacb64e00','Improper integrals of unbounded functions are evaluated using limits as we approach the points of discontinuity.','אינטגרלים לא אמיתיים של פונקציות לא חסומות מוערכים באמצעות גבולות כשאנו מתקרבים לנקודות אי-הרציפות.');
INSERT INTO Translation VALUES('9796977c-4b79-410e-a0a5-dd195749dd5e','Q1: A strictly monotonic function on an interval must be continuous on that interval.','ש1: פונקציה מונוטונית חד-משמעית על מרווח חייבת להיות רציפה על אותו מרווח.');
INSERT INTO Translation VALUES('31e80224-21bc-48e9-957d-7166de9eae19','Q2: In the context of monotonicity continuation, what happens at critical points?','ש2: בהקשר של המשכיות מונוטוניות, מה קורה בנקודות קריטיות?');
INSERT INTO Translation VALUES('748e54a1-b20c-4b54-9d2e-b8bad5169a54','Monotonicity may change or be preserved','המונוטוניות עשויה להשתנות או להישמר');
INSERT INTO Translation VALUES('46ed797d-d5fa-41e5-91a0-a55c2d1ff3a2','Monotonicity always changes','המונוטוניות תמיד משתנה');
INSERT INTO Translation VALUES('b5acc27b-7090-435e-9f94-57dc47fe7f0b','Monotonicity is always preserved','המונוטוניות תמיד נשמרת');
INSERT INTO Translation VALUES('2286337b-ac7f-40d9-8947-d337c023002b','The function becomes undefined','הפונקציה הופכת ללא מוגדרת');
INSERT INTO Translation VALUES('2e26f714-66ac-48b3-a6b1-d75dbd6bdd5c','Q3: How do you determine monotonicity intervals using derivatives?','ש3: איך קובעים מרווחי מונוטוניות באמצעות נגזרות?');
INSERT INTO Translation VALUES('4d0d46e4-31cc-49ec-b15a-4749b36f369b','Find where f''(x) > 0 (increasing) and f''(x) < 0 (decreasing)','מוצאים היכן f''(x) > 0 (עולה) ו f''(x) < 0 (יורדת)');
INSERT INTO Translation VALUES('555f1847-5924-41b6-9732-7b4ded420c72','Find where f(x) > 0 and f(x) < 0','מוצאים היכן f(x) > 0 ו f(x) < 0');
INSERT INTO Translation VALUES('0a810687-1496-417a-b20d-703efcd75ff5','Find where f''''(x) > 0 and f''''(x) < 0','מוצאים היכן f''''(x) > 0 ו f''''(x) < 0');
INSERT INTO Translation VALUES('733847f8-8b46-4ec1-85bd-12755b282e56','Use the intermediate value theorem','משתמשים במשפט ערך הביניים');
INSERT INTO Translation VALUES('9c8d38d1-3ac3-45a3-90d5-53b295a445ce','Q4: What technique is used to extend monotonicity analysis beyond basic intervals?','ש4: איזו טכניקה משמשת להרחבת ניתוח מונוטוניות מעבר למרווחים בסיסיים?');
