INSERT INTO Translation VALUES('1c2c0b8a-7b41-443f-a3ad-437a25196fb7','Integration by parts','אינטגרציה בחלקים');
INSERT INTO Translation VALUES('83e7f088-7ade-4e7d-bdce-40813cdf10fb','Substitution method','שיטת ההצבה');
INSERT INTO Translation VALUES('16b11abb-e4e2-4c04-af42-e24428b78c95','L''Hôpital''s rule','כלל לופיטל');
INSERT INTO Translation VALUES('0f5bdfca-44e1-451b-8752-8d0091d16370','Q5: In advanced monotonicity analysis, what role do inflection points play?','ש5: בניתוח מונוטוניות מתקדם, איזה תפקיד ממלאות נקודות פיתול?');
INSERT INTO Translation VALUES('269aba13-65ed-4ce6-82b5-72f8ce966450','They indicate potential changes in the rate of monotonicity','הן מצביעות על שינויים פוטנציאליים בקצב המונוטוניות');
INSERT INTO Translation VALUES('aa0e39d3-d198-42a2-b20f-38970f71c6a9','They always mark changes in monotonicity direction','הן תמיד מסמנות שינויים בכיוון המונוטוניות');
INSERT INTO Translation VALUES('23368ee0-ad79-4a43-90d3-8da8eb3480a2','They have no impact on monotonicity','אין להן השפעה על המונוטוניות');
