INSERT INTO Translation VALUES('d8447617-582e-47ec-85e9-7827ef45c971','Monotonicity always changes','המונוטוניות תמיד משתנה');
INSERT INTO Translation VALUES('902c503c-24fe-436a-9df7-10f7f34a5c99','Monotonicity is always preserved','המונוטוניות תמיד נשמרת');
