INSERT INTO Translation VALUES('f49dc2b5-cb77-4486-ab4c-b5a7ed723b5e','What is a binary tree?','מה זה עץ בינרי?');
INSERT INTO Translation VALUES('b6963399-3a20-4f2f-a852-903aed400679','A tree where each node has at most two children','עץ שבו לכל צומת יש לכל היותר שני ילדים');
