INSERT INTO Translation VALUES('9be6f98b-fbae-4c1d-b4f5-b90d1477194f','What are the two children of a node in a binary tree called?','איך קוראים לשני הילדים של צומת בעץ בינרי?');
INSERT INTO Translation VALUES('1969be3c-fb50-4cd1-a523-6ef15830dc04','Left child and right child','ילד שמאלי וילד ימני');
INSERT INTO Translation VALUES('49e5c682-1cfc-404b-b06c-ef701d657f3f','First child and second child','ילד ראשון וילד שני');
