INSERT INTO Translation VALUES('5ec7bba2-0df7-4d7f-9520-50829d195b7e','Upper child and lower child','ילד עליון וילד תחתון');
INSERT INTO Translation VALUES('e3b0a0e3-af0c-4661-939d-80d75b3740e7','What is the maximum number of nodes at level k in a binary tree?','מה המספר המקסימלי של צמתים ברמה k בעץ בינרי?');
INSERT INTO Translation VALUES('8c42f5fa-b60e-4114-8306-fa0d0660dc2c','A complete binary tree has all levels filled except possibly the last level.','עץ בינרי שלם כל הרמות מלאות פרט אולי לרמה האחרונה.');
INSERT INTO Translation VALUES('6a9e4211-dab2-4ff4-b9cd-8e0adbdbced0','What is the height of a binary tree with n nodes in the worst case?','מה הגובה של עץ בינרי עם n צמתים במקרה הגרוע ביותר?');
INSERT INTO Translation VALUES('d35d1c57-852c-499d-a647-c0b3dcbc619c','What is an eigenvalue?','מה זה ערך עצמי?');
INSERT INTO Translation VALUES('0663089a-3f86-4f9a-8d4f-9c4a809e829f','A scalar λ such that Av = λv for some non-zero vector v','סקלר λ כך ש-Av = λv עבור וקטור לא-אפס v כלשהו');
