INSERT INTO Translation VALUES('75f26138-ef61-4b92-a0f7-2dba7b5de8c2','What is an eigenvector?','מה זה וקטור עצמי?');
INSERT INTO Translation VALUES('f81124df-c76c-4887-9fcf-9413fc3bf9db','A non-zero vector v such that Av = λv for some scalar λ','וקטור לא-אפס v כך ש-Av = λv עבור סקלר λ כלשהו');
