INSERT INTO Translation VALUES('bce3332b-8920-4270-ac10-5278c7158829','XOR gate','שער XOR');
INSERT INTO Translation VALUES('21d396f2-0f7d-4ce6-bac3-4c4919ae5239','What is the principle behind derangement counting?','מה העיקרון שמאחורי ספירת דרינג׳מנטים?');
INSERT INTO Translation VALUES('086bdcb7-4a8d-4493-91db-372bdc855a7d','Count all permutations then subtract those with fixed points','סופרים את כל התמורות ואז מחסירים את אלה עם נקודות קבועות');
INSERT INTO Translation VALUES('71ff58d4-9e8c-48b0-bfa8-649b699be303','Count only permutations with all fixed points','סופרים רק תמורות עם כל הנקודות הקבועות');
INSERT INTO Translation VALUES('02081428-420c-4613-8d02-241edac7860b','Use direct enumeration only','משתמשים רק בספירה ישירה');
INSERT INTO Translation VALUES('f28a09b4-bfc7-49ec-97d8-a70a909c8d94','Apply the pigeonhole principle','מיישמים את עקרון שובך היונים');
INSERT INTO Translation VALUES('354798b2-97ce-4331-af8e-9abb057ac7a9','How many ways can 6 people be arranged in a line?','בכמה דרכים ניתן לסדר 6 אנשים בתור?');
INSERT INTO Translation VALUES('ba5a08e4-3cb8-4fbb-b7ee-e413fa2988af','If A has 12 elements, B has 8 elements, and their intersection has 5 elements, how many elements are in A only?','אם ל-A יש 12 אלמנטים, ל-B יש 8 אלמנטים, ולחיתוך שלהם יש 5 אלמנטים, כמה אלמנטים יש ב-A בלבד?');
INSERT INTO Translation VALUES('562cdb74-700f-4dbd-b210-abac82f28935','Universal Instantiation allows us to go from universal statements to specific instances.','הכללה אוניברסלית מאפשרת לנו לעבור מהיגדים כלליים למקרים ספציפיים.');
INSERT INTO Translation VALUES('322fc4c6-ab9f-4868-9416-19757553ebc5','What is the implicit derivative of sin(xy) with respect to x?','מה הנגזרת המרומזת של sin(xy) לפי x?');
