INSERT INTO Translation VALUES('0279bec2-df41-4053-aeef-7d47bd4f6380','Define the difference between local and global extrema.','הגדר את ההבדל בין קיצון מקומי וגלובלי.');
INSERT INTO Translation VALUES('82bb9fd9-bc1a-4b6e-befa-262856c9f987','State Fermats theorem for critical points.','הצג את משפט פרמה לנקודות קריטיות.');
