INSERT INTO Translation VALUES('ac4a11b6-59ef-4f2e-bdef-7be1f4676ef0','DFA has exactly one transition per state and symbol, NFA can have multiple or none','ל-DFA יש בדיוק מעבר אחד לכל מצב וסמל, ל-NFA יכולים להיות מספר מעברים או אף אחד');
